window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[154]={"id":"154","numero":154,"titre":"Infection bronchopulmonaire communautaire","objectifs":[{"id":"154-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et identifier les cadres nosologiques des infections respiratoires basses chez l'adulte et chez l'enfant","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">infections respiratoires</span> se divisent en deux grandes catégories topographiques selon que l'atteinte siège au-dessus ou en-dessous des cordes vocales. L'item 154 ne traite que les <span class=\"kw-def\">infections respiratoires basses (IRB)</span> survenant dans un cadre <span class=\"kw-def\">communautaire</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Cadre nosologique</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">IRH</span> — Infections respiratoires hautes</td>\n            <td>Atteinte des voies aériennes <span class=\"kw-def\">sus-glottiques</span> : <span class=\"kw-clinique\">rhinopharyngite</span>, <span class=\"kw-clinique\">otite</span>, <span class=\"kw-clinique\">sinusite</span>, <span class=\"kw-clinique\">angine</span>, <span class=\"kw-clinique\">laryngite</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">IRB</span> — Infections respiratoires basses</td>\n            <td>Atteinte des voies aériennes <span class=\"kw-def\">sous-glottiques</span>. <strong>3 entités</strong> à connaître : <br><strong>Bronchite aiguë :</strong> inflammation des bronches et bronchioles sans atteinte alvéolaire. <br><strong>Exacerbation aiguë de BPCO :</strong> majoration aiguë des symptômes respiratoires d'un patient BPCO. <br><strong>Pneumonie aiguë communautaire (<span class=\"kw-clinique\">PAC</span>) :</strong> inflammation du <span class=\"kw-clinique\">parenchyme pulmonaire</span> avec atteinte alvéolaire.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Communautaire</span></td>\n            <td>Infection <span class=\"kw-etio\">acquise</span> <strong>en dehors d'une structure hospitalière</strong>, OU se déclarant <strong>dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">48 premières heures</span> suivant l'admission à l'hôpital</strong>. <br>Au-delà de <span class=\"kw-chiffre\">48 h</span> = infection <span class=\"kw-alerte\">nosocomiale</span> (mécanismes physiopathologiques et germes différents, hors item 154).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> IRB <span class=\"kw-alerte\">nosocomiales</span> et celles de l'<span class=\"kw-alerte\">immunodéprimé</span> sont particulières quant à leurs mécanismes physiopathologiques et aux agents <span class=\"kw-etio\">infectieux</span> impliqués — elles sortent du cadre de l'item 154.</p>","frequence":0},{"id":"154-2","rang":"A","rubrique":"Etiologie","titre":"Connaître les principaux agents infectieux responsables des infections respiratoires basses et leur fréquence relative, chez l'adulte et chez l'enfant : pneumonies, bronchiolites et bronchites","contenu":"<p>L'<span class=\"kw-def\">agent infectieux</span> n'est <strong>pas identifié dans <span class=\"kw-chiffre\">50-60 %</span> des <span class=\"kw-clinique\">PAC</span></strong> (même prélevées avant ATB). <span class=\"kw-clinique\">Les</span> <strong>infections polymicrobiennes</strong> sont possibles mais rares (<span class=\"kw-chiffre\">&lt; 5 %</span>). Connaître les germes les plus fréquents reste indispensable pour choisir l'<span class=\"kw-ttt\">antibiothérapie probabiliste</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Germe</th><th>Fréquence</th><th><span class=\"kw-def\">Terrain</span> évocateur</th><th>Particularité clinique / <span class=\"kw-ttt\">biologique</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Streptococcus pneumoniae</span></strong> (<span class=\"kw-etio\">pneumocoque</span>)</td>\n            <td><span class=\"kw-chiffre\">~30-60 %</span> des <span class=\"kw-clinique\">PAC</span> documentées ; <span class=\"kw-chiffre\">50 %</span> des PAC hospitalisées</td>\n            <td>Tout âge ; majoré si <span class=\"kw-alerte\">splénectomie</span>, drépanocytaire, <span class=\"kw-clinique\">alcoolique</span>, <span class=\"kw-clinique\">cirrhose</span>, <span class=\"kw-clinique\">BPCO</span>, âge &gt; <span class=\"kw-chiffre\">65 ans</span>, <span class=\"kw-clinique\">immunodépression</span> (<span class=\"kw-etio\">VIH</span>)</td>\n            <td><span class=\"kw-def\">PFLA</span> : début <span class=\"kw-clinique\">brutal</span>, <span class=\"kw-clinique\">fièvre 39-40 °C</span>, <span class=\"kw-clinique\">point de côté</span>, <span class=\"kw-clinique\">expectoration rouille</span> ; récurrence d'<span class=\"kw-clinique\">herpès labial</span> associée ; possible <span class=\"kw-bio\">SIADH</span> (hyponatrémie) chez le sujet âgé</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Mycoplasma pneumoniae</span></strong></td>\n            <td>Atypique fréquent ; 1ʳᵉ cause de <span class=\"kw-def\">PAC ambulatoire</span> du sujet jeune ; épidémies cycliques tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">4-5 ans</span></td>\n            <td>Sujet jeune <span class=\"kw-chiffre\">&lt; 40 ans</span>, contexte <span class=\"kw-clinique\">épidémique</span> (famille, classe, bureau)</td>\n            <td>Début <span class=\"kw-clinique\">progressif</span>, <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&lt; 38,5 °C</span>, <span class=\"kw-clinique\">toux sèche prolongée</span>, tableau pseudo-grippal, <span class=\"kw-clinique\">arthro-myalgies</span> ; <span class=\"kw-bio\">anémie hémolytique à agglutinines froides</span> possible ; <span class=\"kw-bio\">PCR sur prélèvement respiratoire</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Chlamydia pneumoniae</span></strong></td>\n            <td>Atypique</td>\n            <td>Sujet jeune, contexte <span class=\"kw-clinique\">épidémique</span></td>\n            <td>Tableau traînant, <span class=\"kw-clinique\">pharyngite</span> / <span class=\"kw-clinique\">laryngite</span> associée ; diagnostic <span class=\"kw-bio\">PCR</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Legionella pneumophila</span></strong></td>\n            <td>Atypique <span class=\"kw-alerte\">grave</span> (<span class=\"kw-chiffre\">2-5 %</span> des <span class=\"kw-clinique\">PAC</span> hospitalisées) ; <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">10-15 %</span></td>\n            <td>Sujet âgé, <span class=\"kw-clinique\">tabagisme</span>, <span class=\"kw-clinique\">diabète</span>, <span class=\"kw-clinique\">immunodépression</span>, contexte de <span class=\"kw-clinique\">voyage</span> / thermes / aérosols (clim, tour aéroréfrigérante)</td>\n            <td>Tableau sévère, <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">40 °C</span> avec <span class=\"kw-alerte\">pouls dissocié</span>, signes <span class=\"kw-clinique\">digestifs</span> et <span class=\"kw-clinique\">neurologiques</span> (confusion) ; <span class=\"kw-bio\">SIADH</span>, <span class=\"kw-bio\">IRA</span>, <span class=\"kw-bio\">rhabdomyolyse</span>, cytolyse hépatique ; <span class=\"kw-bio\">Ag urinaire sérogroupe 1</span> ; <span class=\"kw-alerte\">DO obligatoire</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Haemophilus influenzae</span></strong></td>\n            <td>Plus rare</td>\n            <td><span class=\"kw-clinique\">BPCO</span>, sujet âgé, tabagique</td>\n            <td>Surinfection bronchique fréquente, tableau peu spécifique</td>\n          </tr>\n          <tr>\n            <td><strong>Virus respiratoires</strong> (<span class=\"kw-etio\">Influenza</span>, <span class=\"kw-etio\">VRS</span>, <span class=\"kw-etio\">SARS-CoV-2</span>, métapneumovirus)</td>\n            <td>Très fréquents en période <span class=\"kw-clinique\">épidémique</span> ; <span class=\"kw-chiffre\">~50 %</span> des <span class=\"kw-clinique\">PAC</span> ; <span class=\"kw-chiffre\">25-50 %</span> des PAC hospitalisées</td>\n            <td>Tout âge ; <span class=\"kw-clinique\">nourrisson +++</span> pour le VRS (bronchiolite)</td>\n            <td>Tableau pseudo-grippal, <span class=\"kw-imagerie\">RXT</span> avec opacités non systématisées bilatérales ; <span class=\"kw-alerte\">surinfection bactérienne secondaire</span> possible (<span class=\"kw-etio\">pneumocoque</span>, staphylocoque)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Staphylococcus aureus</span></strong></td>\n            <td>Rare, <span class=\"kw-alerte\">grave</span></td>\n            <td><span class=\"kw-alerte\">Post-grippal</span> (J5-<span class=\"kw-chiffre\">J7</span>), <span class=\"kw-clinique\">toxicomanie IV</span>, <span class=\"kw-clinique\">mucoviscidose</span>, <span class=\"kw-def\">terrain</span> dégradé</td>\n            <td>Forme grave si <span class=\"kw-alerte\">toxine PVL</span> : <span class=\"kw-alerte\">pneumonie nécrosante / excavée</span>, <span class=\"kw-clinique\">hémoptysie</span>, <span class=\"kw-alerte\">choc</span>, <span class=\"kw-alerte\">SDRA</span></td>\n          </tr>\n          <tr>\n            <td><strong>Entérobactéries</strong> (<span class=\"kw-etio\">Klebsiella</span>, <span class=\"kw-etio\">E. coli</span>) / <strong><span class=\"kw-etio\">Pseudomonas aeruginosa</span></strong></td>\n            <td>Rare hors institution / réa</td>\n            <td>Vie en institution, <span class=\"kw-clinique\">éthylisme chronique</span>, <span class=\"kw-clinique\">BPCO stade 4</span> sous ATB itératifs, <span class=\"kw-clinique\">mucoviscidose</span>, <span class=\"kw-clinique\">bronchectasies</span></td>\n            <td><span class=\"kw-clinique\">PAC</span> sévère, formes <span class=\"kw-alerte\">excavées</span> ; évoquer si <span class=\"kw-alerte\">échec d'une 1ʳᵉ ATB</span> couvrant <span class=\"kw-etio\">pneumocoque</span> + atypiques</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Bronchite aiguë</strong> : étiologie <span class=\"kw-etio\">virale</span> dans <span class=\"kw-chiffre\">90 %</span> des cas (rhinovirus, <span class=\"kw-etio\">influenza</span>, para-influenza, <span class=\"kw-etio\">adénovirus</span>, VRS, métapneumovirus). <strong>Bronchiolite du nourrisson</strong> : <span class=\"kw-etio\">VRS</span> en chef de file (épidémie hivernale), <span class=\"kw-def\">suivi</span> du métapneumovirus et du virus para-influenza.</p>\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong>Réflexe <span class=\"kw-def\">terrain</span></strong> : <span class=\"kw-alerte\">splénectomie</span> = <span class=\"kw-etio\">pneumocoque</span> jusqu'à preuve du contraire (<span class=\"kw-alerte\">urgence</span>). <span class=\"kw-alerte\">Toute immunodépression</span> = évoquer systématiquement la légionellose. <span class=\"kw-clinique\">SIDA</span> = pneumocoque, légionellose, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">pneumocystose</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 166 — <span class=\"kw-etio\">Grippe</span> · 209 — BPCO · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":8},{"id":"154-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie d'une infection respiratoire basse (pneumonie, bronchiolite, bronchite)","contenu":"<p>Physiologiquement, la charge infectieuse dans <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">voies aériennes inférieures</span> est <strong>très faible</strong> grâce à plusieurs <span class=\"kw-def\">barrières de défense</span> :</p>\n      <ul>\n        <li><strong>Mécaniques passives</strong> : voies aériennes supérieures (nez, cornets, pharynx), films liquidiens, épithéliums.</li>\n        <li><strong>Mécaniques actives</strong> : <span class=\"kw-bio\">tapis mucociliaire bronchique</span>, <span class=\"kw-clinique\">réflexe de toux</span>, réflexe épiglottique.</li>\n        <li><strong>Enzymatiques</strong> : <span class=\"kw-bio\">amylase</span> salivaire, <span class=\"kw-bio\">lysozyme</span>, <span class=\"kw-bio\">lactoferrine</span>, inhibiteurs de protéase, <span class=\"kw-bio\">surfactant</span>, fibronectine intra-alvéolaire.</li>\n        <li><strong>Immunologiques</strong> : <span class=\"kw-bio\">IgA de surface</span>, cytokines, <span class=\"kw-bio\">macrophages alvéolaires</span>, <span class=\"kw-bio\">polynucléaires neutrophiles</span>.</li>\n      </ul>\n      <p>L'infection respiratoire résulte d'une <span class=\"kw-def\">dérégulation de ces barrières</span> permettant l'accroissement de la charge infectieuse. <span class=\"kw-clinique\">Les</span> <strong>situations favorisantes</strong> regroupent :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Tabagisme</span> : altération de l'appareil mucociliaire et des macrophages alvéolaires.</li>\n        <li><span class=\"kw-clinique\">Troubles de conscience</span> : inhibition du carrefour oropharyngé et du réflexe de <span class=\"kw-clinique\">toux</span> (favorise l'<span class=\"kw-alerte\">inhalation</span>).</li>\n        <li><span class=\"kw-clinique\">Alcoolisme</span> : <span class=\"kw-etio\">colonisation</span> oropharyngée par des bactéries pathogènes.</li>\n        <li><span class=\"kw-clinique\">Infections virales</span> : altération de l'immunité locale, favorisent <span class=\"kw-clinique\">les</span> surinfections bactériennes secondaires (cf. <span class=\"kw-alerte\">surinfection post-grippale</span>).</li>\n        <li>Âge extrême, <span class=\"kw-clinique\">diabète</span>, <span class=\"kw-clinique\">immunodépression</span>, <span class=\"kw-clinique\">dénutrition</span>.</li>\n      </ul>\n      <p>Selon le <strong>niveau de <span class=\"kw-alerte\">défaillance</span></strong> de ces barrières, l'infection se développe avec un tableau différent :</p>\n      <ul>\n        <li><strong>Bronchite aiguë</strong> = infection limitée aux <span class=\"kw-clinique\">voies aériennes proximales</span> (épithélium trachéo-bronchique), sans atteinte alvéolaire.</li>\n        <li><strong>Bronchiolite</strong> = atteinte des <span class=\"kw-clinique\">bronchioles distales</span> du nourrisson (<span class=\"kw-clinique\">œdème</span> muqueux + obstruction).</li>\n        <li><strong>Pneumonie</strong> = infection étendue aux <span class=\"kw-clinique\">alvéoles</span> (forme la plus évoluée) avec <span class=\"kw-bio\">exsudat alvéolaire</span>, recrutement de PNN, condensation parenchymateuse.</li>\n      </ul>","frequence":0},{"id":"154-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic clinique des infections respiratoires basses (pneumonie, bronchiolite, bronchite)","contenu":"<p>Le diagnostic des IRB repose <strong>en priorité sur la clinique</strong> (interrogatoire + examen physique). La <span class=\"kw-imagerie\">radiographie thoracique</span> n'est <strong>indispensable que pour la <span class=\"kw-clinique\">PAC</span></strong> (obj-6) ; elle n'est <span class=\"kw-alerte\">pas systématique</span> pour la bronchite aiguë ni pour la bronchiolite typique.</p>\n      <p><strong>Interrogatoire</strong> à mener systématiquement :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Terrain</span></strong> : âge, <span class=\"kw-clinique\">comorbidités</span> (BPCO, asthme, IC, IRC, <span class=\"kw-etio\">diabète</span>, immunodépression), <span class=\"kw-clinique\">statut vaccinal</span> (<span class=\"kw-etio\">grippe</span>, <span class=\"kw-etio\">pneumocoque</span>), <span class=\"kw-clinique\">tabagisme</span>, vie en institution.</li>\n        <li><strong>Mode de début</strong> : <span class=\"kw-clinique\">brutal</span> (oriente <span class=\"kw-etio\">pneumocoque</span>) <span class=\"kw-bio\">vs</span> <span class=\"kw-clinique\">progressif</span> (oriente atypique / virus).</li>\n        <li><strong>Signes généraux</strong> : <span class=\"kw-clinique\">fièvre</span> (intensité, courbe), <span class=\"kw-clinique\">frissons</span>, <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">AEG</span>.</li>\n        <li><strong>Signes respiratoires</strong> : <span class=\"kw-clinique\">toux</span> (sèche / productive, <span class=\"kw-clinique\">expectoration</span> purulente / rouille / hémoptoïque), <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">douleur thoracique</span> rythmée par la respiration (réaction pleurale).</li>\n        <li><strong>Signes extra-respiratoires</strong> : <span class=\"kw-clinique\">arthro-myalgies</span>, <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">troubles digestifs</span>, <span class=\"kw-clinique\">troubles neurologiques</span> (oriente atypique / légionellose).</li>\n        <li><strong>Contexte</strong> : <span class=\"kw-clinique\">voyage</span> récent, exposition à des aérosols d'eau, <span class=\"kw-def\">contact</span> malade, période <span class=\"kw-clinique\">épidémique</span> grippale, ATB récente.</li>\n      </ul>\n      <p><strong>Examen physique</strong> structuré :</p>\n      <ul>\n        <li><strong>Constantes</strong> : <span class=\"kw-bio\">FR</span>, <span class=\"kw-bio\">FC</span>, <span class=\"kw-bio\">PA</span>, <span class=\"kw-bio\">T°</span>, <span class=\"kw-bio\">SpO₂</span>, conscience — utiles à la recherche de <span class=\"kw-alerte\">signes de gravité</span> (cf. obj-5).</li>\n        <li><strong>Auscultation pulmonaire</strong> : recherche d'un <span class=\"kw-clinique\">foyer de crépitants</span> localisés (<span class=\"kw-clinique\">syndrome de condensation</span> alvéolaire), <span class=\"kw-clinique\">souffle tubaire</span>, diminution du murmure vésiculaire, <span class=\"kw-clinique\">sibilants</span> diffus (bronchite, bronchiolite).</li>\n        <li><strong>Palpation</strong> : augmentation des <span class=\"kw-clinique\">vibrations vocales</span> en regard d'un foyer.</li>\n        <li><strong>Percussion</strong> : <span class=\"kw-clinique\">matité</span> en regard d'un foyer ou d'un épanchement pleural.</li>\n        <li>Recherche de signes extra-respiratoires (foyer <span class=\"kw-etio\">infectieux</span> ORL, signes digestifs, neurologiques) selon l'orientation.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong>Auscultation peut être normale</strong> dans la <span class=\"kw-clinique\">PAC</span>, en particulier chez le <span class=\"kw-clinique\">sujet âgé</span> ou en cas de foyer postérieur. Le diagnostic clinique seul n'élimine <span class=\"kw-alerte\">jamais</span> une PAC : si suspicion → <span class=\"kw-imagerie\">RXT</span>.\n      </div>","frequence":5},{"id":"154-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des infections respiratoires basses (pneumonie, bronchiolite, bronchite)","contenu":"<table >\n        <thead>\n          <tr><th>Tableau</th><th>Bronchite aiguë</th><th>Bronchiolite (nourrisson)</th><th><span class=\"kw-clinique\">PAC</span> (adulte)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sd général</strong></td>\n            <td><strong><span class=\"kw-clinique\">Fièvre</span> :</strong> inconstante, modérée ; <br><strong>Sd <span class=\"kw-etio\">viral</span> :</strong> <span class=\"kw-clinique\">céphalées</span>, myalgies, <span class=\"kw-clinique\">malaise</span>.</td>\n            <td><strong><span class=\"kw-clinique\">Fièvre</span> :</strong> modérée souvent ; <br><strong><span class=\"kw-clinique\">AEG</span> :</strong> refus alimentaire, irritabilité.</td>\n            <td><strong><span class=\"kw-clinique\">Fièvre</span> :</strong> élevée <span class=\"kw-chiffre\">39-40 °C</span> si <span class=\"kw-etio\">pneumocoque</span> ; <br><strong><span class=\"kw-clinique\">Frissons</span></strong> intenses ; <br><strong><span class=\"kw-clinique\">AEG</span> :</strong> <span class=\"kw-clinique\">asthénie</span> marquée.</td>\n          </tr>\n          <tr>\n            <td><strong>Sd respiratoire</strong></td>\n            <td><strong><span class=\"kw-clinique\">Toux</span> :</strong> prolongée (plusieurs semaines), initialement sèche puis productive (<span class=\"kw-clinique\">expectoration</span> muqueuse ou purulente — <span class=\"kw-alerte\">non synonyme de surinfection bactérienne</span>) ; <br><strong>Douleur :</strong> brûlures thoraciques bilatérales rétro-sternales.</td>\n            <td><strong><span class=\"kw-clinique\">Toux</span> :</strong> sèche puis productive ; <br><strong><span class=\"kw-clinique\">Dyspnée</span> :</strong> <span class=\"kw-clinique\">polypnée</span>, <span class=\"kw-alerte\">tirage</span>, geignement ; <br><strong><span class=\"kw-clinique\">Wheezing</span> :</strong> <span class=\"kw-clinique\">sibilants</span> expiratoires.</td>\n            <td><strong><span class=\"kw-clinique\">Toux</span> :</strong> sèche initiale puis <span class=\"kw-clinique\">expectoration</span> <span class=\"kw-clinique\">purulente</span> ou <span class=\"kw-clinique\">rouille</span> (PFLA) ; <br><strong><span class=\"kw-clinique\">Douleur thoracique</span> :</strong> en <span class=\"kw-clinique\">coup de poignard</span>, rythmée par la respiration ; <br><strong><span class=\"kw-clinique\">Dyspnée</span> :</strong> <span class=\"kw-clinique\">polypnée</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Examen physique</strong></td>\n            <td><strong>Auscultation :</strong> <span class=\"kw-clinique\">râles</span> bronchiques diffus OU normale ; <br><strong>Signe négatif majeur :</strong> <span class=\"kw-alerte\">absence de crépitants en foyer</span>.</td>\n            <td><strong>Auscultation :</strong> <span class=\"kw-clinique\">sibilants</span>, crépitants, sous-crépitants diffus ; <br><strong>Signes de lutte :</strong> <span class=\"kw-alerte\">tirage</span>, balancement, battement des ailes du nez.</td>\n            <td><strong>Sd de condensation :</strong> <span class=\"kw-clinique\">crépitants</span> localisés en foyer, <span class=\"kw-clinique\">souffle tubaire</span>, <span class=\"kw-clinique\">matité</span>, augmentation des vibrations vocales ; <br><strong>Sd pleural</strong> possible : abolition du murmure vésiculaire + matité.</td>\n          </tr>\n          <tr>\n            <td><strong>Pièges</strong></td>\n            <td><span class=\"kw-alerte\">Discordance</span> signes fonctionnels / signes physiques quasi absents ; <br><strong>Pas de <span class=\"kw-clinique\">polypnée</span></strong>, pas de foyer.</td>\n            <td>Recherche de <span class=\"kw-alerte\">signes d'épuisement</span> : pauses respiratoires, apnées, désaturation.</td>\n            <td><strong>Formes atypiques</strong> du sujet âgé : <span class=\"kw-alerte\">troubles du comportement</span>, <span class=\"kw-alerte\">décompensation</span> de <span class=\"kw-def\">comorbidité</span>, signes extra-respiratoires isolés, <span class=\"kw-clinique\">fièvre</span> absente ou inconstante.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong>Formes atypiques fréquentes</strong> chez le sujet âgé, porteur de <span class=\"kw-def\">comorbidités</span> ou <span class=\"kw-clinique\">immunodéprimé</span> : <span class=\"kw-clinique\">fièvre</span> inconstante, <span class=\"kw-alerte\">décompensation d'une comorbidité</span>, révélation par des <span class=\"kw-alerte\">troubles du comportement</span> chez le sujet âgé, signes <span class=\"kw-clinique\">extra-respiratoires</span> (digestifs, arthro-myalgies, neurologiques, <span class=\"kw-clinique\">AEG</span>).\n      </div>","frequence":6},{"id":"154-6","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir rechercher et reconnaître les signes de gravité cliniques et paracliniques","contenu":"<div class=\"callout callout-danger\">\n        🚨 <strong><span class=\"kw-alerte\">Urgence</span> — rechercher systématiquement <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes de gravité</span> devant toute <span class=\"kw-clinique\">PAC</span>.</strong> Le <span class=\"kw-alerte\">bon sens clinique prévaut en toutes circonstances</span>. Toute PAC avec <span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-alerte\">signe de gravité</span>, ≥ 2 <span class=\"kw-def\">facteurs de risque</span>, ou ≥ 1 facteur de risque + âge &gt;<span class=\"kw-chiffre\"> 65 ans</span> = <strong><span class=\"kw-alerte\">hospitalisation</span> recommandée</strong>.\n      </div>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Atteinte des fonctions vitales</strong></td>\n            <td><strong>Conscience :</strong> <span class=\"kw-alerte\">altération</span>, confusion, troubles de la vigilance ; <br><strong>FR :</strong> <span class=\"kw-chiffre\">≥ 30/min</span> ; <br><strong>FC :</strong> <span class=\"kw-chiffre\">≥ 120 bpm</span> ; <br><strong>PA :</strong> <span class=\"kw-chiffre\">PAs &lt; 90 mmHg</span> ou <span class=\"kw-chiffre\">PAd ≤ 60 mmHg</span>, marbrures ; <br><strong>T° :</strong> <span class=\"kw-chiffre\">&lt; 36 °C</span> ou <span class=\"kw-chiffre\">&gt; 40 °C</span> ; <br><strong>SpO₂ :</strong> hypoxémie nécessitant O₂.</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td><span class=\"kw-clinique\">Cyanose</span>, <span class=\"kw-clinique\">tirage</span>, <span class=\"kw-clinique\">marbrures</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Complications locorégionales</strong></td>\n            <td><span class=\"kw-alerte\">Empyème pleural</span>, <span class=\"kw-alerte\">excavation pulmonaire</span>, atteinte radiologique <span class=\"kw-alerte\">bilatérale ou multilobaire</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Atteintes extra-pulmonaires / systémiques</strong></td>\n            <td><strong>Rein :</strong> <span class=\"kw-alerte\">insuffisance rénale aiguë</span> ; <br><strong>Foie :</strong> <span class=\"kw-alerte\">insuffisance hépatocellulaire</span> ; <br><strong>Coagulation :</strong> <span class=\"kw-alerte\">CIVD</span> (la thrombopénie doit alerter) ; <br><strong>Hémato :</strong> <span class=\"kw-bio\">leuconeutropénie &lt; 4 G/L</span>, <span class=\"kw-bio\">thrombopénie &lt; 100 G/L</span> ; <br><strong>Métabolique :</strong> <span class=\"kw-bio\">hyperlactatémie</span>, acidose sévère.</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs aggravants</strong></td>\n            <td><span class=\"kw-alerte\">Échec d'une ATB ambulatoire préalable</span> ; <br>Exposition récente aux <span class=\"kw-ci\">AINS</span> ; <br><span class=\"kw-alerte\">Pneumonie d'inhalation</span> (trouble de la déglutition) ; <br>Pneumonie obstructive sur obstacle trachéo-bronchique.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span> à risque</strong></td>\n            <td><strong>Âge :</strong> <span class=\"kw-chiffre\">≥ 65 ans</span> (âge physiologique &gt; âge civil) ; <br><strong><span class=\"kw-def\">Comorbidités</span> :</strong> intoxication alcoolo-tabagique, <span class=\"kw-ci\">insuffisance cardiaque</span>, maladie cérébrovasculaire, IRC, hépatopathie chronique, <span class=\"kw-etio\">diabète</span> mal équilibré, BPCO avec TVO, néoplasie évolutive, <span class=\"kw-clinique\">immunodépression</span>, drépanocytose homozygote, <span class=\"kw-alerte\">splénectomie</span> ; <br><strong>Antécédents :</strong> pneumonie <span class=\"kw-etio\">bactérienne</span>, <span class=\"kw-alerte\">hospitalisation</span> dans l'année, vie en institution.</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Score</span> CRB65 (clinique pur)</h4>\n      <p>Le <span class=\"kw-def\">CRB65</span> est le <span class=\"kw-def\">score</span> de référence en ville pour décider de l'orientation après diagnostic clinique de <span class=\"kw-clinique\">PAC</span> (la SpO₂ ne fait pas partie du score).</p>\n      <ul>\n        <li><strong>C</strong>onfusion mentale.</li>\n        <li><strong>R</strong>espiration : <span class=\"kw-chiffre\">FR ≥ 30/min</span>.</li>\n        <li><strong>B</strong>lood pressure : <span class=\"kw-chiffre\">PAs &lt; 90 mmHg</span> (à ne pas confondre avec <span class=\"kw-chiffre\">&lt; 100</span> du <span class=\"kw-chiffre\">qSOFA</span>) ou <span class=\"kw-chiffre\">PAd ≤ 60 mmHg</span>.</li>\n        <li><strong>65</strong> : âge <span class=\"kw-chiffre\">≥ 65 ans</span> (physiologique).</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Score</span> CRB65</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr><td><strong>0 critère</strong></td><td>Traitement <span class=\"kw-clinique\">ambulatoire</span> possible.</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">≥ 1</span> critère</strong></td><td><span class=\"kw-alerte\">Évaluation hospitalière</span> recommandée.</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Critères d'admission en <span class=\"kw-alerte\">USI</span> / réanimation</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Critères majeurs</span> (1 suffit)</strong> : <span class=\"kw-alerte\">choc septique</span> nécessitant des vasopresseurs ; <span class=\"kw-alerte\">insuffisance respiratoire aiguë</span> nécessitant une <span class=\"kw-ttt\">intubation</span>.</li>\n        <li><strong><span class=\"kw-def\">Critères mineurs</span> (3 sur 9 suffisent)</strong> : <span class=\"kw-bio\">FR ≥ 30/min</span>, <span class=\"kw-bio\">PaO₂/FiO₂ ≤ 250</span>, atteinte multilobaire, confusion, urémie, <span class=\"kw-bio\">leucopénie &lt; 4 G/L</span>, <span class=\"kw-bio\">thrombopénie &lt; 100 G/L</span>, <span class=\"kw-bio\">hypothermie &lt; 36 °C</span>, <span class=\"kw-clinique\">hypotension</span> nécessitant remplissage.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong>CRB65 ne s'utilise que lorsque le diagnostic de <span class=\"kw-clinique\">PAC</span> est posé</strong> (après réalisation de la <span class=\"kw-imagerie\">RXT</span>). Il ne se substitue jamais à l'examen clinique global ni à l'évaluation du <span class=\"kw-def\">terrain</span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Spécificités pédiatriques — <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> d'une <span class=\"kw-clinique\">PAC</span> de l'enfant 🚩</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Terrain</span> :</strong> âge <span class=\"kw-chiffre\">&lt; 6 mois</span> ; <span class=\"kw-def\">comorbidité</span> (cardiopathie sous-jacente, pathologie pulmonaire chronique, <span class=\"kw-alerte\">drépanocytose</span>, immunosuppression).</li>\n        <li><strong>Respiratoire :</strong> FR très élevée pour l'âge, intensité des <span class=\"kw-alerte\">signes de lutte</span>, <span class=\"kw-alerte\">cyanose</span>, <span class=\"kw-alerte\">SpO₂ &lt; 95 % sous air</span>.</li>\n        <li><strong>Général :</strong> <span class=\"kw-alerte\">aspect toxique</span>, troubles hémodynamiques, <span class=\"kw-clinique\">sueurs</span>, troubles de conscience, difficultés à s'alimenter.</li>\n        <li><strong><span class=\"kw-imagerie\">RXT</span> :</strong> pneumonie très étendue (<span class=\"kw-chiffre\">≥ 2 lobes</span>), <span class=\"kw-clinique\">adénopathies</span> intertrachéobronchiques.</li>\n        <li><strong>Complications locales :</strong> <span class=\"kw-alerte\">abcès</span>, <span class=\"kw-alerte\">épanchement pleural</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Gravité de la bronchiolite aiguë du nourrisson — grille HAS 2019</h4>\n      <p>Évaluation <strong>toujours après désobstruction rhinopharyngée (DRP)</strong>. Noter la date de début des signes de lutte (risque d'aggravation dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">48 premières heures</span>).</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Forme légère</th><th>Forme modérée</th><th>Forme grave</th></tr></thead>\n        <tbody>\n          <tr><td><strong>État général</strong></td><td>Non altéré</td><td>Non altéré</td><td><span class=\"kw-alerte\">Altéré</span></td></tr>\n          <tr><td><strong>FR (/min)</strong></td><td><span class=\"kw-chiffre\">&lt; 60</span></td><td><span class=\"kw-chiffre\">60-69</span></td><td><span class=\"kw-chiffre\">≥ 70</span>, ou respiration superficielle, ou <span class=\"kw-clinique\">bradypnée</span> <span class=\"kw-chiffre\">&lt; 30</span>, ou <span class=\"kw-alerte\">apnée</span></td></tr>\n          <tr><td><strong>FC (/min)</strong></td><td>Normale</td><td>Normale</td><td><span class=\"kw-chiffre\">&gt; 180</span> ou <span class=\"kw-chiffre\">&lt; 80</span></td></tr>\n          <tr><td><strong>Muscles accessoires</strong></td><td>Absent / léger</td><td>Modéré</td><td>Intense</td></tr>\n          <tr><td><strong>SpO₂ (<span class=\"kw-def\">air</span> ambiant, éveil)</strong></td><td><span class=\"kw-chiffre\">&gt; 92 %</span></td><td><span class=\"kw-chiffre\">90-92 %</span> → <span class=\"kw-alerte\">hospitalisation</span></td><td><span class=\"kw-alerte\">≤ 90 %</span> ou <span class=\"kw-clinique\">cyanose</span></td></tr>\n          <tr><td><strong>Alimentation</strong></td><td><span class=\"kw-chiffre\">&gt; 50 %</span></td><td><span class=\"kw-chiffre\">&lt; 50 %</span> sur 3 prises</td><td><span class=\"kw-ttt\">Réduction</span> importante ou <span class=\"kw-alerte\">refus</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Interprétation :</strong> légère = tous <span class=\"kw-clinique\">les</span> critères présents ; modérée = <span class=\"kw-chiffre\">≥ 1</span> critère modéré ; grave = ≥ 1 critère grave. <strong><span class=\"kw-def\">Critères de</span> vulnérabilité :</strong> prématurité <span class=\"kw-chiffre\">&lt; 36 SA</span>, âge <span class=\"kw-chiffre\">&lt; 2 mois</span> (âge corrigé, risque d'apnées), indication de palivizumab, <span class=\"kw-def\">comorbidités</span> (dysplasie bronchopulmonaire, cardiopathie <span class=\"kw-etio\">congénitale</span> à shunt, déficit immunitaire, maladie neuromusculaire / polyhandicap), contexte social défavorable.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span></em></p>","frequence":8},{"id":"154-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications à la réalisation d'une radio de thorax chez l'adulte et chez l'enfant","contenu":"<p>La <span class=\"kw-imagerie\">radiographie thoracique de face</span> est le <strong>seul examen complémentaire systématique</strong> dans la <span class=\"kw-clinique\">PAC</span> : le <span class=\"kw-def\">diagnostic positif</span> repose le plus souvent sur <strong>clinique + <span class=\"kw-imagerie\">RXT</span></strong>. Elle est ± complétée d'un cliché de <span class=\"kw-imagerie\">profil</span> en cas de doute.</p>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Indication <span class=\"kw-imagerie\">RXT</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Adulte — suspicion de <span class=\"kw-clinique\">PAC</span></strong></td>\n            <td><span class=\"kw-imagerie\">RXT de face systématique</span>. Permet : confirmation diagnostique, repérage d'un <span class=\"kw-clinique\">syndrome de condensation</span>, recherche d'une complication (épanchement, excavation), bilan de base avant ATB.</td>\n          </tr>\n          <tr>\n            <td><strong>Adulte — bronchite aiguë</strong></td>\n            <td><span class=\"kw-alerte\">Pas de RXT systématique</span>. Indiquée <strong>en cas de doute clinique</strong> sur une pneumonie ou de signes inquiétants.</td>\n          </tr>\n          <tr>\n            <td><strong>Enfant — bronchiolite typique</strong></td>\n            <td><span class=\"kw-alerte\">Pas de RXT systématique</span>. Indiquée si <span class=\"kw-alerte\">signes de gravité</span>, doute diagnostique, suspicion de surinfection ou de complication.</td>\n          </tr>\n          <tr>\n            <td><strong>Enfant — suspicion de <span class=\"kw-clinique\">PAC</span></strong></td>\n            <td><span class=\"kw-imagerie\">RXT de face</span> recommandée pour confirmation et recherche de complication (pleuropneumopathie).</td>\n          </tr>\n          <tr>\n            <td><strong>Sémiologie attendue</strong></td>\n            <td><strong>Pneumonie alvéolaire :</strong> <span class=\"kw-imagerie\">condensation systématisée</span> segmentaire ou lobaire, homogène, bien limitée, avec <span class=\"kw-imagerie\">bronchogramme aérien</span> ; <br><strong>Pneumonie interstitielle :</strong> opacités infiltratives uni- ou bilatérales, non systématisées, réticulations / micronodules ; <br><strong>Bronchopneumonie :</strong> nodules disséminés hétérogènes, prédominance péri-hilaire.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong>Retard radiologique par rapport à la clinique</strong> possible (la <span class=\"kw-imagerie\">RXT</span> peut être normale à <span class=\"kw-chiffre\">H0</span>). Un foyer peut aussi être <span class=\"kw-alerte\">masqué par les structures anatomiques</span> (cœur, coupole). Aucun signe radiologique n'est <span class=\"kw-alerte\">spécifique d'un micro-organisme</span>.\n      </div>\n      <p><strong><span class=\"kw-imagerie\">RXT</span> de contrôle</strong> à <span class=\"kw-chiffre\">4-6 semaines</span> : recommandée chez le <span class=\"kw-clinique\">tabagique</span> ou patient &gt; <span class=\"kw-chiffre\">50 ans</span> après <span class=\"kw-clinique\">PAC</span> pour ne pas méconnaître un <span class=\"kw-alerte\">cancer bronchique</span> sous-jacent.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant · 309 — Tumeurs du poumon</em></p>","frequence":5},{"id":"154-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de la documentation microbiologique de l'infection en fonction du tableau clinique et du terrain","contenu":"<p>La <span class=\"kw-bio\">documentation microbiologique</span> est <strong>rare en pratique</strong> (agent <span class=\"kw-etio\">infectieux</span> non identifié dans <span class=\"kw-chiffre\">50-60 %</span> des <span class=\"kw-clinique\">PAC</span>, même prélevées avant ATB). Elle est <strong>réservée aux patients hospitalisés</strong> ; en ambulatoire, aucun examen microbiologique n'est requis. Elle doit être effectuée <strong>avant l'<span class=\"kw-ttt\">antibiothérapie</span></strong> mais ne doit jamais en retarder l'instauration.</p>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th><span class=\"kw-bio\">Hémocultures</span></th><th>ECBC</th><th>Antigénuries</th><th>Autres</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Ambulatoire</strong></td>\n            <td>Non</td>\n            <td>Non</td>\n            <td>Non</td>\n            <td>Aucun examen microbiologique.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle</strong></td>\n            <td><span class=\"kw-bio\">2 paires</span> avant ATB (positivité <span class=\"kw-chiffre\">20-30 %</span> des <span class=\"kw-clinique\">PAC</span> graves)</td>\n            <td>Si <span class=\"kw-clinique\">expectoration</span> productive ; interprétable si <span class=\"kw-bio\">PNN &gt; 25/champ</span>, cellules buccales <span class=\"kw-bio\">&lt; 10/champ</span>, flore monomorphe ≥ <span class=\"kw-chiffre\">10⁷</span> bactéries/mL</td>\n            <td><span class=\"kw-bio\">Ag urinaire Légionelle</span> si symptômes évocateurs, instabilité hémodynamique, hypoxémie, ou contexte épidémique (sérogroupe 1, <span class=\"kw-chiffre\">90-95 %</span> des légionelloses, non décapité par l'ATB)</td>\n            <td>Liquide pleural si épanchement ; <span class=\"kw-bio\">PCR multiplex nasopharyngée</span> en période épidémique (novembre-février) ; <span class=\"kw-bio\">dépistage VIH</span> systématiquement proposé.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">USI</span> / Réanimation</strong></td>\n            <td>Oui systématique</td>\n            <td>Oui</td>\n            <td><span class=\"kw-bio\">Ag Légionelle + Ag pneumocoque</span> (le <span class=\"kw-etio\">pneumocoque</span> n'a d'intérêt qu'en <span class=\"kw-alerte\">USI</span>/réa selon le Pilly)</td>\n            <td>Aspiration endo-bronchique si patient intubé ; <span class=\"kw-bio\">PCR multiplex nasopharyngée</span> (avec <span class=\"kw-etio\">grippe</span> en période épidémique) ; liquide pleural si épanchement.</td>\n          </tr>\n          <tr>\n            <td><strong>Immunodéprimé</strong></td>\n            <td>Oui</td>\n            <td>Oui</td>\n            <td>Ag Légionelle</td>\n            <td>Recherche de <span class=\"kw-etio\">Pneumocystis jirovecii</span> (<span class=\"kw-clinique\">expectoration</span> induite, LBA, <span class=\"kw-bio\">antigène</span> <span class=\"kw-bio\">β-D-glucane</span>) ; bilan extensif selon immunodépression.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan <span class=\"kw-ttt\">biologique</span> standard</strong> de tout patient hospitalisé pour <span class=\"kw-clinique\">PAC</span> : <span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">bilan hépatique</span>, hémostase ; <span class=\"kw-bio\">gazométrie artérielle</span> si SpO₂ basse ou mauvaise tolérance (recherche d'hypoxémie par <span class=\"kw-bio\">shunt</span>, hypercapnie, <span class=\"kw-bio\">hyperlactatémie</span>).</p>\n      <div class=\"callout callout-info\">\n        💡 <strong>Anomalies ioniques évocatrices :</strong> <span class=\"kw-bio\">SIADH</span> (hyponatrémie hypo-osmolaire normovolémique) très évocateur de <span class=\"kw-alerte\">légionellose</span> ; <span class=\"kw-bio\">insuffisance rénale aiguë</span> également plus fréquente dans la légionellose. <span class=\"kw-bio\">2 antigénuries Légionelle négatives à 72 h</span> excluent le diagnostic avec <span class=\"kw-chiffre\">90 %</span> de certitude.\n      </div>","frequence":12},{"id":"154-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la place de l'échographie pleuro-pulmonaire, en particulier en pédiatrie","contenu":"<p>L'<span class=\"kw-imagerie\">échographie pleuro-pulmonaire</span> (lung ultrasound, LUS) est un examen <strong>non irradiant</strong>, reproductible, réalisable au lit du malade, et particulièrement performant pour le diagnostic et le <span class=\"kw-def\">suivi</span> des <span class=\"kw-clinique\">PAC</span>. Elle remplace progressivement la <span class=\"kw-imagerie\">RXT</span> dans certaines indications, notamment <span class=\"kw-clinique\">pédiatriques</span> et en <span class=\"kw-alerte\">réanimation</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Indication</th><th>Apport diagnostique</th><th>Signes attendus</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Détection d'un <span class=\"kw-imagerie\">épanchement pleural</span></strong></td>\n            <td><strong>Sensibilité :</strong> <span class=\"kw-chiffre\">&gt; 90 %</span>, supérieure à la <span class=\"kw-imagerie\">RXT</span> pour <span class=\"kw-clinique\">les</span> petits épanchements ; <br><strong>Aide à la quantification</strong> et au guidage de la <span class=\"kw-clinique\">ponction pleurale</span>.</td>\n            <td>Plage <span class=\"kw-imagerie\">anéchogène</span> entre <span class=\"kw-clinique\">les</span> feuillets pleural et viscéral ; <span class=\"kw-imagerie\">signe du quadrilatère</span>, signe sinusoïdal.</td>\n          </tr>\n          <tr>\n            <td><strong>Identification d'une <span class=\"kw-imagerie\">condensation parenchymateuse</span></strong></td>\n            <td>Performante si condensation sous-pleurale ; <span class=\"kw-bio\">complément</span> utile à la <span class=\"kw-imagerie\">RXT</span>.</td>\n            <td><strong><span class=\"kw-imagerie\">Hépatisation pulmonaire</span></strong> (parenchyme d'échogénicité hépatique), <span class=\"kw-imagerie\">bronchogramme aérien dynamique</span>, perte du sliding pleural sur la zone.</td>\n          </tr>\n          <tr>\n            <td><strong>Pédiatrie</strong></td>\n            <td><strong>Alternative à la <span class=\"kw-imagerie\">TDM thoracique</span></strong> pour limiter l'<span class=\"kw-alerte\">irradiation</span> ; utile pour le diagnostic de pleuropneumopathie.</td>\n            <td><span class=\"kw-imagerie\">Lignes B</span> confluentes en zone consolidée ; <span class=\"kw-imagerie\">épanchement pleural</span> facilement visualisé.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Réanimation</span></strong></td>\n            <td>Outil de <strong>monitoring au lit</strong> du patient ventilé ; <span class=\"kw-def\">diagnostic différentiel</span> <span class=\"kw-alerte\">SDRA</span> / <span class=\"kw-alerte\">OAP</span> / pneumonie en <span class=\"kw-bio\">complément</span> de la clinique.</td>\n            <td><strong>Profil B</strong> (lignes B diffuses) = <span class=\"kw-clinique\">œdème</span> ; <strong>Profil C</strong> (condensations) = pneumonie ; <strong>Profil A</strong> (lignes A + sliding) = poumon normal.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Suivi</span> évolutif</strong></td>\n            <td>Régression de la condensation et de l'épanchement sous ATB ; détection précoce d'un <span class=\"kw-alerte\">empyème</span> (cloisonnement).</td>\n            <td><span class=\"kw-imagerie\">Échos internes</span>, cloisons <span class=\"kw-imagerie\">hyperéchogènes</span>, organisation pleurale.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        💡 <strong>Atout pédiatrique :</strong> chez l'<span class=\"kw-clinique\">enfant</span>, l'écho pleuro-pulmonaire évite la <span class=\"kw-imagerie\">TDM</span> dans la majorité des indications de complication de <span class=\"kw-clinique\">PAC</span>. Elle est devenue l'examen de 2ᵉ ligne après la <span class=\"kw-imagerie\">RXT</span> en cas de doute sur un épanchement ou un foyer sous-pleural. Sa réalisation suppose un <strong>opérateur entraîné</strong>.\n      </div>\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong>Limites :</strong> <span class=\"kw-alerte\">opérateur-dépendante</span>, peu performante pour <span class=\"kw-clinique\">les</span> foyers centraux non sous-pleuraux, ne remplace pas la <span class=\"kw-imagerie\">TDM</span> si suspicion de <span class=\"kw-alerte\">tumeur sous-jacente</span> ou d'<span class=\"kw-alerte\">embolie pulmonaire</span>. Contenu enrichi via Collège CEP / Pilly 2024 — fiches sources locales muettes sur cet objectif.\n      </div>","frequence":0},{"id":"154-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l'indication de la tomodensitométrie dans les infections respiratoires basses","contenu":"<p>La <span class=\"kw-imagerie\">TDM thoracique</span> (non injectée en 1ʳᵉ intention) n'est <strong>pas indiquée systématiquement</strong> dans la <span class=\"kw-clinique\">PAC</span>. Elle reste un examen de seconde ligne, à indications précises, en <span class=\"kw-bio\">complément</span> de la <span class=\"kw-imagerie\">RXT de face</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Indication</th><th>Justification</th><th>Modalité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic positif</span> difficile</strong></td>\n            <td><span class=\"kw-imagerie\">RXT</span> d'interprétation incertaine, <span class=\"kw-clinique\">sujet âgé</span>, <span class=\"kw-clinique\">pathologie pulmonaire sous-jacente</span> (BPCO, fibrose, séquelles).</td>\n            <td><span class=\"kw-imagerie\">TDM sans injection</span>, coupes fines.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic étiologique</span></strong></td>\n            <td><span class=\"kw-def\">Terrain</span> particulier (<span class=\"kw-clinique\">immunodépression</span>), recherche d'une cause <span class=\"kw-alerte\">obstructive</span> (tumeur endobronchique, corps étranger).</td>\n            <td><span class=\"kw-imagerie\">TDM</span> sans injection ; <span class=\"kw-imagerie\">injection</span> si suspicion vasculaire.</td>\n          </tr>\n          <tr>\n            <td><strong>Recherche de complication locorégionale</strong></td>\n            <td><span class=\"kw-alerte\">Épanchement pleural</span> abondant ou cloisonné, <span class=\"kw-alerte\">empyème</span>, <span class=\"kw-alerte\">excavation</span>, <span class=\"kw-alerte\">abcès pulmonaire</span>, <span class=\"kw-alerte\">fistule bronchopleurale</span>.</td>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> injectée</strong> (rehaussement pariétal pleural si <span class=\"kw-clinique\">empyème</span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span> défavorable sous ATB</strong></td>\n            <td>Persistance ou aggravation clinique à <span class=\"kw-chiffre\">48-72 h</span> (cf. obj-14) : rechercher pneumonie compliquée ou erreur diagnostique.</td>\n            <td><span class=\"kw-imagerie\">TDM</span> injectée le plus souvent.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic différentiel</span></strong></td>\n            <td>Suspicion d'<span class=\"kw-alerte\">embolie pulmonaire</span> (réaliser alors une <span class=\"kw-imagerie\">angio-TDM</span>), <span class=\"kw-alerte\">pneumopathie interstitielle diffuse</span>, <span class=\"kw-alerte\">cancer bronchique</span>, <span class=\"kw-alerte\">vascularite</span>.</td>\n            <td><span class=\"kw-imagerie\">TDM</span> injectée (angio-protocole si EP) ; coupes <span class=\"kw-imagerie\">haute résolution</span> si PID.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        ⚠️ La <span class=\"kw-imagerie\">TDM</span> doit toujours être réalisée <strong>avant</strong> une <span class=\"kw-bio\">endoscopie bronchique</span> éventuelle (sinon, risque de fausses images infiltratives post-lavage). Chez l'<span class=\"kw-clinique\">enfant</span>, lui préférer l'<span class=\"kw-imagerie\">échographie pleuro-pulmonaire</span> dès que possible pour limiter l'<span class=\"kw-alerte\">irradiation</span>.\n      </div>\n      <div class=\"callout callout-info\">\n        🎯 <strong>À ne pas oublier en QCM :</strong> une <span class=\"kw-alerte\">pneumopathie excavée</span> persistante chez un <span class=\"kw-clinique\">fumeur</span> impose la <span class=\"kw-imagerie\">TDM</span> pour rechercher en priorité un <span class=\"kw-alerte\">cancer bronchique</span> (cf. obj-14), une <span class=\"kw-alerte\">tuberculose</span> (cf. item 159), ou un <span class=\"kw-alerte\">infarctus pulmonaire</span>.\n      </div>","frequence":3},{"id":"154-11","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie de thorax avec pneumopathie franche lobaire aiguë (PFLA)","contenu":"<p>La <span class=\"kw-def\">pneumopathie franche lobaire aiguë (PFLA)</span> est la forme classique de la pneumonie à <span class=\"kw-etio\">pneumocoque</span>. Sa sémiologie radiologique sur la <span class=\"kw-imagerie\">RXT de face</span> est stéréotypée :</p>\n      <ul>\n        <li><strong>Opacité alvéolaire</strong> de densité <span class=\"kw-imagerie\">homogène</span>.</li>\n        <li><strong>Caractère <span class=\"kw-imagerie\">systématisé</span></strong> : occupe un segment ou un lobe entier, en respectant <span class=\"kw-clinique\">les</span> limites anatomiques.</li>\n        <li><strong>Limites <span class=\"kw-imagerie\">nettes</span></strong> : bord scissural rectiligne (la scissure forme la limite supérieure / inférieure du foyer).</li>\n        <li><strong><span class=\"kw-imagerie\">Bronchogramme aérien</span></strong> visible au sein de l'opacité (présence d'<span class=\"kw-def\">air</span> dans <span class=\"kw-clinique\">les</span> bronches non remplies par l'exsudat) — signe clé pour différencier d'une atélectasie.</li>\n        <li><strong>Pas de rétraction</strong> du parenchyme (différentiel : atélectasie obstructive).</li>\n        <li><strong>Pas de signe d'épanchement</strong> initial le plus souvent (à rechercher en cas d'<span class=\"kw-clinique\">évolution</span> défavorable).</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/154/rxt-pfla-pneumocoque.png\" alt=\"Radiographie thoracique de face : pneumopathie franche lobaire aiguë à pneumocoque — opacité alvéolaire systématisée homogène d'un lobe, à limites scissurales nettes, avec bronchogramme aérien et sans rétraction\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie de thorax de face</span> — <span class=\"kw-def\">PFLA à pneumocoque</span> : <span class=\"kw-radio\">opacité alvéolaire systématisée homogène</span> occupant un lobe, à <span class=\"kw-radio\">limites scissurales nettes</span>, avec <span class=\"kw-radio\">bronchogramme aérien</span> et <strong>sans rétraction</strong> (différentiel : atélectasie).</figcaption>\n      </figure>\n      <p><strong>Corrélation clinique</strong> : <span class=\"kw-clinique\">foyer de crépitants</span> localisé, <span class=\"kw-clinique\">souffle tubaire</span>, <span class=\"kw-clinique\">matité</span> en regard. Le tableau associe : début <span class=\"kw-clinique\">brutal</span>, <span class=\"kw-clinique\">fièvre 39-40 °C</span>, <span class=\"kw-clinique\">point de côté thoracique</span>, <span class=\"kw-clinique\">expectoration rouille</span>.</p>\n      <div class=\"callout callout-info\">\n        🎯 <strong>Réflexe EDN :</strong> opacité alvéolaire systématisée avec bronchogramme aérien = <span class=\"kw-etio\">PFLA à pneumocoque</span> jusqu'à preuve du contraire → <span class=\"kw-ttt\">amoxicilline 1 g x 3/j PO</span> en 1ʳᵉ intention chez l'adulte ambulatoire sans gravité.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":11,"liens":[{"href":"https://radiopaedia.org/articles/pneumonia","label":"Radiopaedia : Pneumonia"},{"href":"https://radiopaedia.org/articles/lobar-pneumonia","label":"Radiopaedia : Lobar pneumonia"},{"href":"https://radiopaedia.org/articles/atypical-pneumonia","label":"Radiopaedia : Atypical pneumonia"},{"href":"https://radiopaedia.org/articles/legionella-pneumonia","label":"Radiopaedia : Legionella pneumonia"},{"href":"https://radiopaedia.org/articles/viral-respiratory-tract-infection-1","label":"Radiopaedia : Viral respiratory tract infection"},{"href":"https://radiopaedia.org/articles/silhouette-sign-x-rays","label":"Radiopaedia : Silhouette sign (Rx)"},{"href":"https://radiopaedia.org/cases/large-pleural-effusion-infant-3","label":"Radiopaedia : Large pleural effusion (cas pédia)"},{"href":"https://radiopaedia.org/articles/bronchiolitis","label":"Radiopaedia : Bronchiolitis"},{"href":"https://radiopaedia.org/cases/bronchiolitis-2","label":"Radiopaedia : Bronchiolitis (cas)"}]},{"id":"154-12","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie thoracique de face : pleuropneumopathie de l'enfant","contenu":"<p>La <span class=\"kw-def\">pleuropneumopathie de l'enfant</span> associe une <span class=\"kw-imagerie\">condensation parenchymateuse</span> et un <span class=\"kw-imagerie\">épanchement pleural</span> homolatéral. Elle survient majoritairement en complication d'une <span class=\"kw-clinique\">PAC</span> à <span class=\"kw-etio\">pneumocoque</span> (parfois <span class=\"kw-etio\">Staphylococcus aureus</span>) et impose une PEC hospitalière.</p>\n      <table >\n        <thead>\n          <tr><th>Signe radiologique</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Opacité du foyer pneumonique</strong></td>\n            <td><span class=\"kw-imagerie\">Condensation alvéolaire</span> systématisée, homogène, avec <span class=\"kw-imagerie\">bronchogramme aérien</span> au sein du foyer.</td>\n          </tr>\n          <tr>\n            <td><strong>Opacité pleurale</strong></td>\n            <td>Opacité dense, à <span class=\"kw-imagerie\">limite supérieure concave en haut et en dehors</span> (ligne de Damoiseau-Ellis classique sur <span class=\"kw-imagerie\">RXT</span> debout), homogène, masquant le diaphragme.</td>\n          </tr>\n          <tr>\n            <td><strong>Effacement du <span class=\"kw-imagerie\">cul-de-sac pleural</span></strong></td>\n            <td>Comblement du sinus costo-diaphragmatique latéral ; effacement de la coupole diaphragmatique homolatérale.</td>\n          </tr>\n          <tr>\n            <td><strong>Déviation médiastinale</strong></td>\n            <td>Vers le <strong>côté controlatéral</strong> si épanchement abondant (déplacement du cœur, refoulement trachéal) ; absente si épanchement modéré.</td>\n          </tr>\n          <tr>\n            <td><strong>Scoliose <span class=\"kw-ttt\">antalgique</span></strong></td>\n            <td><span class=\"kw-clinique\">Concavité homolatérale</span> possible chez l'enfant en raison de la douleur.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Confirmation et caractérisation</strong> par <span class=\"kw-imagerie\">échographie pleurale</span> systématique (cf. obj-8) : quantification, cloisonnement, guidage de la <span class=\"kw-clinique\">ponction pleurale</span> diagnostique et évacuatrice. La <span class=\"kw-bio\">ponction pleurale</span> avec analyse <span class=\"kw-bio\">cytochimique et bactériologique</span> (cellularité, <span class=\"kw-bio\">pH</span>, <span class=\"kw-bio\">glucose</span>, protides, Gram, culture, <span class=\"kw-bio\">antigène pneumocoque</span>) est indiquée dès que l'épanchement est significatif.</p>\n      <div class=\"callout callout-info\">\n        🎯 <strong>Critères d'<span class=\"kw-alerte\">empyème pleural</span> (<span class=\"kw-clinique\">pleurésie purulente</span>) chez l'enfant :</strong> pus franc à la <span class=\"kw-ttt\">ponction</span> OU <span class=\"kw-bio\">pH &lt; 7,2</span> OU <span class=\"kw-bio\">glucose &lt; 2,2 mmol/L</span> OU <span class=\"kw-bio\">LDH élevés</span> OU germe au Gram/culture. Impose un <span class=\"kw-ttt\">drainage thoracique</span> en plus de l'<span class=\"kw-ttt\">antibiothérapie</span> prolongée.\n      </div>\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong>Image à fournir :</strong> ajouter une <span class=\"kw-imagerie\">RXT</span> pédiatrique illustrative dans <code>assets/images/154/pleuropneumopathie-enfant.png</code> dès que disponible (Collège de Pédiatrie, banque iconographique perso). À ce jour, sémiologie textuelle seule.\n      </div>","frequence":2},{"id":"154-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de première intention des infections respiratoires basses chez l'adulte et l'enfant","contenu":"<p>L'<span class=\"kw-def\">antibiothérapie probabiliste</span> de la <span class=\"kw-clinique\">PAC</span> est <strong>urgente</strong> (après prélèvements microbiologiques si possible — sauf en ambulatoire où aucun prélèvement n'est réalisé) et doit <strong>toujours couvrir le <span class=\"kw-etio\">pneumocoque</span></strong> (sauf rare cas du sujet jeune en ambulatoire évocateur de bactérie atypique).</p>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>ATB de 1ʳᵉ intention</th><th>Échec à<span class=\"kw-chiffre\"> 48-72 h</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Adulte ambulatoire — sujet sain sans gravité</strong></td>\n            <td><strong>Molécule :</strong> <span class=\"kw-ttt\">amoxicilline 1 g × 3/j PO</span> (cible <span class=\"kw-etio\">pneumocoque</span>) OU <span class=\"kw-ttt\">macrolide</span> si suspicion d'atypique ; <br><strong>Alternative :</strong> <span class=\"kw-ttt\">pristinamycine PO</span> ; <br><strong>Durée :</strong> <span class=\"kw-chiffre\">7 jours</span>.</td>\n            <td>Switch entre <span class=\"kw-ttt\">amoxicilline</span> et macrolide ; si aggravation rapide → <span class=\"kw-alerte\">hospitalisation</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Adulte ambulatoire — <span class=\"kw-def\">comorbidité</span> / sujet âgé / éthylique</strong></td>\n            <td><strong>Molécules :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique PO</span> OU <span class=\"kw-ttt\">C3G injectable</span> (<span class=\"kw-ttt\">céfotaxime</span>, <span class=\"kw-ttt\">ceftriaxone</span>) OU <span class=\"kw-ttt\">FQAP</span> (<span class=\"kw-ttt\">lévofloxacine</span>) ; <br><strong>Durée :</strong> <span class=\"kw-chiffre\">7 jours</span>.</td>\n            <td><span class=\"kw-alerte\">Hospitalisation</span> (CEP) ou ajout d'un <span class=\"kw-ttt\">macrolide</span> (Pilly).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle — <span class=\"kw-etio\">pneumocoque</span> suspecté/documenté</strong></td>\n            <td><strong>Molécule :</strong> <span class=\"kw-ttt\">amoxicilline</span> PO/IV ; <br><strong>Switch oral :</strong> à <span class=\"kw-chiffre\">J3</span> si apyrexie <span class=\"kw-chiffre\">≥ 24 h</span> et stabilité clinique.</td>\n            <td><span class=\"kw-def\">Réévaluation</span> ; ajout macrolide si suspicion d'atypique.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle — sujet âgé / <span class=\"kw-def\">comorbidité</span></strong></td>\n            <td><strong>Molécules :</strong> <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> OU <span class=\"kw-ttt\">C3G injectable</span> (<span class=\"kw-ttt\">céfotaxime</span>, <span class=\"kw-ttt\">ceftriaxone</span>) OU <span class=\"kw-ttt\">FQAP</span> (<span class=\"kw-ttt\">lévofloxacine</span>).</td>\n            <td>Ajout d'un <span class=\"kw-ttt\">macrolide</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">USI</span> / réanimation — cas général</strong></td>\n            <td><strong>Bithérapie systématique :</strong> <span class=\"kw-ttt\">C3G injectable + macrolide IV</span> OU <span class=\"kw-ttt\">C3G injectable + lévofloxacine IV</span>.</td>\n            <td><span class=\"kw-def\">Réévaluation</span>, élargissement du spectre.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">USI</span> / réa — FdR de <span class=\"kw-etio\">Pseudomonas</span></strong> (BPCO <span class=\"kw-def\">stade</span> 4 + ATB itératifs, mucoviscidose, bronchectasies)</td>\n            <td><strong><span class=\"kw-ttt\">Trithérapie</span> :</strong> <span class=\"kw-ttt\">β-lactamine antipyocyanique</span> (céfépime, <span class=\"kw-ttt\">pipéracilline-tazobactam</span> ou carbapénème) + <span class=\"kw-ttt\">amikacine</span> ou <span class=\"kw-ttt\">tobramycine</span> (max <span class=\"kw-chiffre\">3-5 j</span>) + <span class=\"kw-ttt\">macrolide IV</span> ou <span class=\"kw-ttt\">lévofloxacine IV</span> (couverture Légionelle).</td>\n            <td>Adaptation à l'<span class=\"kw-bio\">antibiogramme</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Nourrisson — bronchiolite aiguë</strong> (VRS, &lt;<span class=\"kw-chiffre\"> 12 mois</span>)</td>\n            <td><strong>Pas d'<span class=\"kw-ttt\">antibiothérapie</span> ❌</strong> ni de traitement spécifique (aucun n'a démontré son efficacité, HAS 2019). PEC symptomatique : <span class=\"kw-ttt\">désobstruction rhinopharyngée (DRP)</span> + <span class=\"kw-ttt\">fractionnement de l'alimentation</span> ; formes hospitalisées : <span class=\"kw-ttt\">oxygénothérapie</span>, support nutritionnel (nutrition entérale ou hydratation IV), <span class=\"kw-ttt\">support ventilatoire</span> (lunettes haut débit ou CPAP) si aggravation sous O₂. <strong>Pas de</strong> <span class=\"kw-ci\">bronchodilatateurs</span>, <span class=\"kw-ci\">corticoïdes</span> ni <span class=\"kw-ci\">kinésithérapie de drainage</span> de routine.</td>\n            <td><span class=\"kw-def\">Surveillance</span> pluriquotidienne <span class=\"kw-clinique\">les</span> 48 premières heures (risque de dégradation rapide) ; avis spécialisé si signes respiratoires quotidiens &gt;<span class=\"kw-chiffre\"> 1 mois</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Enfant</strong></td>\n            <td><strong>Molécule :</strong> <span class=\"kw-ttt\">amoxicilline PO 80-100 mg/kg/j</span> en 3 prises, max <span class=\"kw-chiffre\">3 g/j</span> (cible <span class=\"kw-etio\">pneumocoque</span>) ; <br><strong>Durée :</strong> <span class=\"kw-chiffre\">5 jours</span> ; <br><strong>Suspicion mycoplasme</strong> (&gt;<span class=\"kw-chiffre\"> 3 ans</span>) → <span class=\"kw-ttt\">macrolide</span> ; <br><strong><span class=\"kw-ci\">Allergie</span> pénicilline</strong> → <span class=\"kw-ttt\">C3G injectable</span> ; <span class=\"kw-ttt\">pristinamycine</span> possible après <span class=\"kw-chiffre\">&gt; 6 ans</span>.</td>\n            <td><span class=\"kw-def\">Réévaluation</span> à<span class=\"kw-chiffre\"> 48-72 h</span> ; si <span class=\"kw-imagerie\">RXT</span> inchangée → switch macrolide ; si épanchement → <span class=\"kw-alerte\">hospitalisation</span> + ATB IV.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>ATB à ne pas utiliser</strong> dans la <span class=\"kw-clinique\">PAC</span> : <span class=\"kw-ci\">céphalosporines orales</span> (mauvaise biodisponibilité), <span class=\"kw-ci\">cyclines</span>, <span class=\"kw-ci\">triméthoprime-sulfaméthoxazole</span>. <span class=\"kw-clinique\">Les</span> <span class=\"kw-ci\">FQAP</span> ne doivent pas être prescrites si une <span class=\"kw-ttt\">fluoroquinolone</span> a été reçue dans les <span class=\"kw-chiffre\">3 derniers mois</span>.</p>\n      <p><strong>Traitements associés</strong> en <span class=\"kw-alerte\">hospitalisation</span> : <span class=\"kw-ttt\">oxygénothérapie</span> (corr<span class=\"kw-chiffre\">ige</span> l'hypoxémie de shunt) ; remplissage par <span class=\"kw-ttt\">NaCl 0,9 % 30 mL/kg</span> ± <span class=\"kw-ttt\">noradrénaline</span> si <span class=\"kw-clinique\">hypotension</span> persistante ; <span class=\"kw-ttt\">kinésithérapie de drainage bronchique systématique</span> ; <span class=\"kw-ttt\">oseltamivir 75 mg × 2/j PO × 5 jours</span> (adulte) ou <span class=\"kw-ttt\">2 mg/kg × 2/j</span> (enfant <span class=\"kw-chiffre\">≥ 1 an</span>, max <span class=\"kw-chiffre\">75 mg/dose</span>) si suspicion de <span class=\"kw-etio\">grippe</span> en période épidémique. <span class=\"kw-ci\">VNI inutile</span> dans la <span class=\"kw-clinique\">PAC</span> ; <span class=\"kw-ci\">corticothérapie systémique non démontrée</span>.</p>\n      <p><strong>Durée totale :</strong> <span class=\"kw-chiffre\">7 jours</span> pour la <span class=\"kw-clinique\">PAC</span> « tout venant » ; <span class=\"kw-chiffre\">8-14 jours</span> pour germes atypiques / Légionelle non grave ; <span class=\"kw-chiffre\">21 jours</span> pour <span class=\"kw-alerte\">légionellose grave</span> ou immunodéprimé.</p>\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong><span class=\"kw-def\">Réévaluation</span> clinique obl<span class=\"kw-chiffre\">iga</span>toire à<span class=\"kw-chiffre\"> 48-72 h</span></strong> quel que soit le lieu de PEC (cf. obj-14). Le patient doit être capable de contacter un médecin si dégradation.\n      </div>","frequence":16},{"id":"154-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la bronchite aiguë (pas d'antibiothérapie, pas d'anti-inflammatoires non stéroïdiens (AINS), pas d'anti-tussifs)","contenu":"<p>La <span class=\"kw-def\">bronchite aiguë</span> de l'adulte sain est une infection <span class=\"kw-etio\">virale</span> dans <span class=\"kw-chiffre\">90 %</span> des cas. Le traitement est <strong>symptomatique et ambulatoire</strong> exclusivement.</p>\n      <div class=\"callout callout-danger\">\n        ❌ <strong>Pas d'<span class=\"kw-ttt\">antibiothérapie</span></strong> chez l'adulte sain (BPCO inclus en l'absence d'exacerbation). L'origine <span class=\"kw-etio\">virale</span> rend l'ATB inefficace et favorise la résistance bactérienne.\n      </div>\n      <div class=\"callout callout-danger\">\n        ❌ <strong>Pas d'<span class=\"kw-ttt\">AINS</span>.</strong> Risque démontré de <span class=\"kw-alerte\">surinfection cutanée</span> et de <span class=\"kw-alerte\">complications pleurales</span> (<span class=\"kw-clinique\">empyème</span>) si bascule vers une PAC.\n      </div>\n      <div class=\"callout callout-danger\">\n        ❌ <strong>Pas d'anti-tussifs.</strong> Risque d'<span class=\"kw-alerte\">encombrement bronchique</span> et de surinfection. Pas de <span class=\"kw-ci\">corticoïdes</span> systémiques ni inhalés, pas de <span class=\"kw-ci\">mucolytiques</span>, pas d'<span class=\"kw-ci\">expectorants</span> (potentiellement délétères).\n      </div>\n      <p><strong>Traitement recommandé :</strong></p>\n      <ul>\n        <li><strong>Symptomatique :</strong> <span class=\"kw-ttt\">paracétamol</span> si <span class=\"kw-clinique\">fièvre</span> / inconfort.</li>\n        <li><strong>Hydratation</strong> orale abondante, repos.</li>\n        <li><strong>Information du patient</strong> sur la durée prolongée des symptômes.</li>\n      </ul>\n      <p><strong><span class=\"kw-clinique\">Évolution</span></strong> spontanément favorable : disparition de la <span class=\"kw-clinique\">fièvre</span> et des signes respiratoires en <span class=\"kw-chiffre\">3 jours</span> ; <span class=\"kw-clinique\">toux post-infectieuse</span> persistante jusqu'à <span class=\"kw-chiffre\">3 semaines</span> (n'est pas un échec). En cas de persistance au-delà → <strong>reconsidérer le diagnostic</strong>.</p>\n      <p><strong>Examen complémentaire :</strong> aucun n'est justifié. En cas de doute clinique sur une <span class=\"kw-clinique\">PAC</span> → <span class=\"kw-imagerie\">RXT de face</span>.</p>","frequence":0},{"id":"154-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la réévaluation de l'évolution et de l'adaptation de la prise en charge en cas d'évolution défavorable","contenu":"<p>Toute <span class=\"kw-clinique\">PAC</span> doit être <strong>réévaluée cliniquement à <span class=\"kw-chiffre\">48-72 h</span></strong> de l'introduction de l'<span class=\"kw-ttt\">antibiothérapie</span>, quel que soit le lieu de PEC (ambulatoire ou hospitalier). Objectifs : juger de l'<strong>efficacité</strong> et de la <strong>tolérance</strong> du traitement.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-clinique\">Évolution</span> favorable</h4>\n      <ul>\n        <li><strong>Amélioration clinique</strong> attendue à <span class=\"kw-chiffre\">72 h</span> — ne signifie pas forcément <span class=\"kw-alerte\">apyrexie stricte</span> (<span class=\"kw-clinique\">fièvre</span> parfois prolongée <span class=\"kw-chiffre\">5 jours</span>, surtout avec bactéries intracellulaires).</li>\n        <li><strong>En ambulatoire</strong> : pas de désescalade antibiotique (pas de microbiologie).</li>\n        <li><strong>En <span class=\"kw-alerte\">hospitalisation</span></strong> : <span class=\"kw-ttt\">désescalade thérapeutique</span> à envisager si résultats microbiologiques fiables et amélioration sous l'ATB en cours ; <span class=\"kw-ttt\">switch oral</span> à <span class=\"kw-chiffre\">J3</span> si apyrétique <span class=\"kw-chiffre\">24 h</span> et stabilité.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-clinique\">Évolution</span> défavorable</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Patient hospitalisé</strong></td>\n            <td><strong>Causes de l'échec :</strong> <span class=\"kw-alerte\">pneumonie compliquée</span> (épanchement, <span class=\"kw-clinique\">abcès</span>, excavation), ATB inadaptée (germe résistant, hors spectre), erreur diagnostique ; <br><strong>Examens :</strong> <span class=\"kw-imagerie\">TDM thoracique</span>, prélèvements invasifs (LBA, brossage, prélèvement distal protégé), <span class=\"kw-ttt\">drainage</span> d'un épanchement pleural ; <br><strong>Ré-escalade ATB</strong> à discuter selon contexte.</td>\n          </tr>\n          <tr>\n            <td><strong>Patient ambulatoire</strong></td>\n            <td><strong>Si ATB initiale sans <span class=\"kw-etio\">pneumocoque</span> :</strong> couvrir le pneumocoque (<span class=\"kw-ttt\">amoxicilline</span>) ; <br><strong>Si ATB initiale était <span class=\"kw-ttt\">pristinamycine</span> ou <span class=\"kw-ttt\">FQAP</span> active sur <span class=\"kw-clinique\">les</span> 3 cibles classiques :</strong> <span class=\"kw-alerte\">hospitalisation</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Causes possibles d'échec de l'<span class=\"kw-ttt\">antibiothérapie</span></h4>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Mécanisme / Exemples</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mauvaise observance</strong></td>\n            <td>Oubli de prises, arrêt prématuré, <span class=\"kw-ci\">intolérance</span> digestive non signalée.</td>\n            <td>Interrogatoire ciblé ; <span class=\"kw-ttt\">switch IV</span> en <span class=\"kw-alerte\">hospitalisation</span> si doute.</td>\n          </tr>\n          <tr>\n            <td><strong>Problème pharmacocinétique</strong></td>\n            <td>Patient <span class=\"kw-clinique\">obèse</span>, <span class=\"kw-clinique\">3ᵉ secteur</span> (<span class=\"kw-clinique\">ascite</span>, <span class=\"kw-clinique\">œdèmes</span>), <span class=\"kw-clinique\">insuffisance rénale</span>, malabsorption.</td>\n            <td>Adaptation posologique, dosages plasmatiques si critère, voie IV.</td>\n          </tr>\n          <tr>\n            <td><strong>Germe hors spectre</strong></td>\n            <td>Entérobactéries résistantes, <span class=\"kw-etio\">SARM</span>, <span class=\"kw-etio\">Pseudomonas aeruginosa</span>, <span class=\"kw-etio\">Mycobacterium tuberculosis</span> (BK), <span class=\"kw-etio\">Pneumocystis jirovecii</span>.</td>\n            <td><span class=\"kw-bio\">Prélèvements microbiologiques</span> (LBA, brossage), élargissement / réadaptation ATB.</td>\n          </tr>\n          <tr>\n            <td><strong>Complication locale</strong></td>\n            <td><span class=\"kw-alerte\">Empyème pleural</span> non drainé, <span class=\"kw-alerte\">abcès pulmonaire</span>, <span class=\"kw-alerte\">excavation</span>.</td>\n            <td><span class=\"kw-imagerie\">TDM thoracique</span>, <span class=\"kw-ttt\">drainage</span> si épanchement, ATB prolongée.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Erreur diagnostique</span></strong></td>\n            <td><span class=\"kw-alerte\">Embolie pulmonaire</span>, <span class=\"kw-alerte\">cancer bronchique</span>, <span class=\"kw-alerte\">tuberculose</span>, <span class=\"kw-alerte\">vascularite</span> (<span class=\"kw-clinique\">Wegener</span>), <span class=\"kw-alerte\">aspergillose</span>, pneumopathie d'<span class=\"kw-ci\">hypersensibilité</span>.</td>\n            <td>Reprise du <span class=\"kw-def\">diagnostic différentiel</span> ; imagerie ciblée (<span class=\"kw-imagerie\">angio-TDM</span>, <span class=\"kw-imagerie\">TDM HR</span>), biologie spécialisée, <span class=\"kw-ttt\">biopsie</span> si besoin.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong>Pneumopathie excavée</strong> persistante → évoquer en priorité : <span class=\"kw-alerte\">cancer bronchique</span> (caractère irrégulier de l'opacité, fumeur), <span class=\"kw-alerte\">tuberculose</span>, <span class=\"kw-alerte\">infarctus pulmonaire</span>, <span class=\"kw-alerte\">vascularite</span> (<span class=\"kw-clinique\">Wegener</span>), <span class=\"kw-alerte\">aspergillose</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":4},{"id":"154-16","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications des pneumopathies aiguës communautaires et des bronchiolites","contenu":"<table >\n        <thead>\n          <tr><th>Complication</th><th>Mécanisme</th><th>Diagnostic</th><th>Prise en charge</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Pleurésie parapneumonique</strong> (non purulente)</td>\n            <td>Effusion réactionnelle stérile</td>\n            <td><span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-imagerie\">échographie pleurale</span></td>\n            <td><span class=\"kw-def\">Surveillance</span> ; <span class=\"kw-ttt\">ponction</span> si abondante.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Empyème pleural</span></strong></td>\n            <td>Surinfection <span class=\"kw-etio\">bactérienne</span> du liquide pleural</td>\n            <td><span class=\"kw-clinique\">Ponction pleurale</span> : pus franc, <span class=\"kw-bio\">pH &lt; 7,2</span>, glucose bas, bactériologie</td>\n            <td><span class=\"kw-ttt\">Drainage thoracique</span> + ATB prolongée.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Abcès pulmonaire</span> / excavation</strong></td>\n            <td><span class=\"kw-clinique\">Nécrose</span> parenchymateuse</td>\n            <td><span class=\"kw-imagerie\">TDM thoracique</span> : image hydro-aérique</td>\n            <td>ATB prolongée (<span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ou C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> + <span class=\"kw-ttt\">métronidazole</span>) ± <span class=\"kw-ttt\">drainage</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Sepsis</span> / <span class=\"kw-alerte\">choc septique</span></strong></td>\n            <td><span class=\"kw-alerte\">Défaillance</span> hémodynamique</td>\n            <td><span class=\"kw-bio\">Hémocultures</span>, <span class=\"kw-bio\">lactates</span>, défaillances d'organe</td>\n            <td><span class=\"kw-alerte\">Réanimation</span>, ATB IV, expansion volémique, vasopresseurs.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Décompensation</span> d'une <span class=\"kw-def\">comorbidité</span></strong></td>\n            <td>Stress <span class=\"kw-etio\">infectieux</span></td>\n            <td>Clinique : <span class=\"kw-ci\">insuffisance cardiaque</span>, déséquilibre diabétique, <span class=\"kw-alerte\">AVC</span></td>\n            <td>PEC de la <span class=\"kw-def\">comorbidité</span> en parallèle.</td>\n          </tr>\n          <tr>\n            <td><strong>Complications infectieuses à distance</strong></td>\n            <td>Dissémination bactériémique</td>\n            <td><span class=\"kw-bio\">Hémocultures</span>, imagerie ciblée, <span class=\"kw-imagerie\">ETT/ETO</span> si <span class=\"kw-clinique\">endocardite</span></td>\n            <td>ATB prolongée selon site (<span class=\"kw-alerte\">méningite</span>, péricardite, arthrite, <span class=\"kw-clinique\">endocardite</span> à <span class=\"kw-etio\">pneumocoque</span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">SDRA</span></strong> / <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</td>\n            <td>Atteinte alvéolaire diffuse</td>\n            <td><span class=\"kw-bio\">GDS</span>, <span class=\"kw-imagerie\">TDM</span></td>\n            <td><span class=\"kw-ttt\">Oxygénothérapie</span> à haut débit, VNI ou <span class=\"kw-ttt\">intubation</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Bronchiolite — complications</strong></td>\n            <td><span class=\"kw-ci\">Insuffisance respiratoire</span> aiguë, <span class=\"kw-alerte\">apnée du nourrisson</span>, surinfection <span class=\"kw-etio\">bactérienne</span></td>\n            <td><span class=\"kw-def\">Surveillance</span> scopée, <span class=\"kw-bio\">SpO₂</span>, <span class=\"kw-imagerie\">RXT</span> si surinfection</td>\n            <td><span class=\"kw-alerte\">Hospitalisation</span>, désobstruction nasale, O₂ ± alimentation entérale.</td>\n          </tr>\n          <tr>\n            <td><strong>Décès</strong></td>\n            <td><span class=\"kw-def\">Mortalité</span> globale <span class=\"kw-chiffre\">2-5 %</span> ; <span class=\"kw-chiffre\">&lt; 3 %</span> en ambulatoire ; <span class=\"kw-chiffre\">7 %</span> si hospitalisé ; <span class=\"kw-chiffre\">40 %</span> chez l'âgé institutionnalisé ou en <span class=\"kw-alerte\">réanimation</span></td>\n            <td>—</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-clinique\">Endocardite</span> infectieuse · 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span></em></p>","frequence":1},{"id":"154-17","rang":"A","rubrique":"Prévention","titre":"Connaître les principaux terrains à risque de pneumonie et les principes de la prévention vaccinale","contenu":"<p>La <span class=\"kw-def\">prévention vaccinale</span> de la <span class=\"kw-clinique\">PAC</span> repose sur 2 vaccins : <span class=\"kw-ttt\">vaccin antigrippal annuel</span> et <span class=\"kw-ttt\">vaccin antipneumococcique</span> séquentiel (VPC13 puis VPP23).</p>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Terrain</span> à risque</th><th>Vaccin <span class=\"kw-etio\">pneumocoque</span></th><th><span class=\"kw-etio\">Grippe</span> annuelle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Nourrisson</strong> (<span class=\"kw-ttt\">calendrier vaccinal</span> obl<span class=\"kw-chiffre\">iga</span>toire depuis 2018)</td>\n            <td><span class=\"kw-ttt\">VPC13</span> obl<span class=\"kw-chiffre\">iga</span>toire : M2 → M4 → rappel M11</td>\n            <td>Recommandée selon situation.</td>\n          </tr>\n          <tr>\n            <td><strong>Âge <span class=\"kw-chiffre\">≥ 65 ans</span></strong></td>\n            <td>Recommandé : <span class=\"kw-ttt\">VPC13</span> puis <span class=\"kw-ttt\">VPP23</span> <span class=\"kw-chiffre\">≥ 2 mois</span> après</td>\n            <td>Recommandée.</td>\n          </tr>\n          <tr>\n            <td><strong>Pneumo</strong> : <span class=\"kw-clinique\">BPCO</span>, asthme sévère, IRC respiratoire, emphysème</td>\n            <td>Recommandé</td>\n            <td>Recommandée.</td>\n          </tr>\n          <tr>\n            <td><strong>Cardio</strong> : <span class=\"kw-ci\">insuffisance cardiaque</span>, cardiopathie <span class=\"kw-etio\">congénitale</span> cyanogène, coronaropathie, <span class=\"kw-alerte\">AVC</span></td>\n            <td>Recommandé</td>\n            <td>Recommandée.</td>\n          </tr>\n          <tr>\n            <td><strong>Métabo / Néphro / Hépato</strong> : <span class=\"kw-clinique\">diabète mal équilibré</span>, IRC, <span class=\"kw-clinique\">syndrome néphrotique</span>, hépatopathie chronique</td>\n            <td>Recommandé</td>\n            <td>Recommandée.</td>\n          </tr>\n          <tr>\n            <td><strong>Immunodéprimés</strong> : <span class=\"kw-alerte\">asplénie</span> / splénectomie, drépanocytose, <span class=\"kw-etio\">VIH</span>, greffe, chimio, <span class=\"kw-ttt\">biothérapie</span>, <span class=\"kw-ttt\">corticothérapie</span> prolongée</td>\n            <td>Recommandé — schéma renforcé ; <span class=\"kw-alerte\">urgence si splénectomie</span></td>\n            <td>Recommandée.</td>\n          </tr>\n          <tr>\n            <td><strong>Brèche ostéo-méningée / implants cochléaires</strong></td>\n            <td>Recommandé</td>\n            <td>Recommandée.</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Schéma vaccinal <span class=\"kw-etio\">pneumocoque</span> chez l'adulte à risque</h4>\n      <ul>\n        <li><strong>Naïf de <span class=\"kw-ttt\">vaccination</span> :</strong> 1 dose de <span class=\"kw-ttt\">VPC13</span> (vaccin conjugué) → puis 1 dose de <span class=\"kw-ttt\">VPP23</span> (polysaccharidique) ≥ <span class=\"kw-chiffre\">2 mois</span> plus tard.</li>\n        <li><strong>Rappel</strong> par <span class=\"kw-ttt\">VPP23</span> à <span class=\"kw-chiffre\">≥ 5 ans</span> si risque persistant.</li>\n        <li><strong>Délai minimum <span class=\"kw-chiffre\">≥ 2 mois</span></strong> entre VPC13 et VPP23 (risque d'<span class=\"kw-ci\">hyporéactivité</span> si trop rapprochés).</li>\n        <li><strong>Co-administration possible</strong> avec le <span class=\"kw-ttt\">vaccin antigrippal</span>.</li>\n      </ul>\n      <p><strong>Enfant à risque &lt;<span class=\"kw-chiffre\"> 2 ans</span></strong> : 3 doses de <span class=\"kw-ttt\">VPC13</span>. Entre <span class=\"kw-chiffre\">2 et 5 ans</span> non vacciné antérieurement : 2 doses de <span class=\"kw-ttt\">VPC13</span> puis 1 dose de <span class=\"kw-ttt\">VPP23</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 209 — BPCO</em></p>","frequence":5},{"id":"154-18","rang":"A","rubrique":"Prévention","titre":"Connaître les mesures d'hygiène à adopter en collectivité","contenu":"<p>La prévention des infections broncho-pulmonaires repose sur la <strong><span class=\"kw-ttt\">vaccination</span></strong>, <span class=\"kw-clinique\">les</span> <strong>mesures d'hygiène</strong>, le <strong>contrôle des <span class=\"kw-def\">facteurs de risque</span></strong>, et la <strong>déclaration obl<span class=\"kw-chiffre\">iga</span>toire</strong> pour certains pathogènes.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-ttt\">Vaccination</span> antipneumococcique</h4>\n      <table >\n        <thead>\n          <tr><th>Vaccin</th><th>Population cible</th><th>Schéma</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">VPC13</span></strong> (vaccin pneumococcique conjugué 13-valent — Prevenar 13<sup>®</sup>)</td>\n            <td><strong>Nourrisson :</strong> tous (<span class=\"kw-chiffre\">2 mois</span>,<span class=\"kw-chiffre\"> 4 mois</span>,<span class=\"kw-chiffre\"> 11 mois</span>) ; <br><strong>Adulte à risque :</strong> immunodéprimé, <span class=\"kw-alerte\">asplénie</span>, <span class=\"kw-clinique\">drépanocytose</span>, <span class=\"kw-clinique\">IRC</span>, <span class=\"kw-clinique\">syndrome néphrotique</span>, <span class=\"kw-clinique\">fistule</span> <span class=\"kw-bio\">LCS</span>, candidat ou porteur d'implant cochléaire, <span class=\"kw-ci\">insuffisance respiratoire</span> chronique, <span class=\"kw-clinique\">BPCO sévère</span>, <span class=\"kw-etio\">tabagisme</span> important, <span class=\"kw-etio\">alcoolisme</span> avec hépatopathie, <span class=\"kw-clinique\">diabète</span>.</td>\n            <td>Schéma adulte : <strong>1 dose <span class=\"kw-ttt\">VPC13</span></strong> puis <span class=\"kw-ttt\">VPP23</span> <strong>≥ <span class=\"kw-chiffre\">8 semaines</span> plus tard</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">VPP23</span></strong> (vaccin pneumococcique polyosidique 23-valent — Pneumovax<sup>®</sup>)</td>\n            <td>Mêmes indications adulte que VPC13, en <strong><span class=\"kw-bio\">complément</span> séquentiel</strong>.</td>\n            <td><span class=\"kw-chiffre\">≥ 8 semaines</span> après <span class=\"kw-ttt\">VPC13</span> ; <strong>rappel à <span class=\"kw-chiffre\">5 ans</span></strong> si <span class=\"kw-def\">terrain</span> à très haut risque (asplénie, immunodéprimé, <span class=\"kw-clinique\">syndrome néphrotique</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-ttt\">Vaccination</span> antigrippale annuelle</h4>\n      <p>Vaccin <strong>inactivé tétravalent</strong>, recommandé chaque automne (octobre-décembre) chez : sujet <span class=\"kw-chiffre\">≥ 65 ans</span>, <span class=\"kw-clinique\">professionnel de santé</span>, <span class=\"kw-clinique\">femme enceinte</span> (à tout terme), entourage de nourrisson à risque, et toutes <span class=\"kw-clinique\">les</span> populations cibles du <span class=\"kw-ttt\">VPC13</span> listées ci-dessus (<span class=\"kw-clinique\">immunodépression</span>, <span class=\"kw-def\">comorbidités</span> respiratoires, cardiovasculaires, métaboliques). <strong>Co-administration possible</strong> avec le <span class=\"kw-ttt\">vaccin antipneumococcique</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-ttt\">Vaccination</span> anti-COVID-19</h4>\n      <p>Rappel annuel recommandé chez <span class=\"kw-clinique\">les</span> populations à risque (<span class=\"kw-chiffre\">≥ 65 ans</span>, <span class=\"kw-clinique\">immunodéprimés</span>, <span class=\"kw-def\">comorbidités</span>). Schéma calé sur la campagne <span class=\"kw-etio\">grippe</span> en automne.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-ttt\">Vaccination</span> anticoquelucheuse</h4>\n      <p>Stratégie du <strong>cocooning</strong> (entourage du nourrisson) ; rappel à <span class=\"kw-chiffre\">25 ans</span> dans le <span class=\"kw-ttt\">calendrier vaccinal</span> adulte ; vaccination de la <span class=\"kw-clinique\">femme enceinte</span> recommandée à partir du 2ᵉ trimestre.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Mesures d'hygiène et de prévention non vaccinale</h4>\n      <ul>\n        <li><strong>Hygiène des mains</strong> : <span class=\"kw-clinique\">lavage savon</span> ou <span class=\"kw-clinique\">solution hydro-alcoolique</span> systématique en milieu de soins, en période épidémique.</li>\n        <li><strong>Hygiène respiratoire</strong> : mouchoirs à usage unique, <span class=\"kw-clinique\">masque chirurgical</span> si <span class=\"kw-clinique\">toux</span> fébrile, distance physique.</li>\n        <li><strong><span class=\"kw-ttt\">Sevrage</span> tabagique</strong> : <span class=\"kw-def\">facteur de risque</span> majeur de <span class=\"kw-clinique\">PAC</span> et de complications ; à proposer systématiquement.</li>\n        <li><strong>Hygiène bucco-dentaire</strong> : prévention des <span class=\"kw-alerte\">pneumonies d'inhalation</span>, en particulier chez le sujet âgé et l'institutionnalisé.</li>\n        <li><strong>Entretien des installations à risque</strong> de <span class=\"kw-etio\">Legionella</span> : <span class=\"kw-clinique\">tours aéroréfrigérantes</span>, ballons d'eau chaude (T° &gt; <span class=\"kw-chiffre\">50 °C</span>), spa, brumisateurs (responsabilité du gestionnaire de l'établissement).</li>\n        <li><strong>Éviction temporaire</strong> selon germe : <span class=\"kw-alerte\">coqueluche</span> jusqu'à 5 j d'ATB, <span class=\"kw-alerte\">tuberculose</span> pulmonaire bacillifère jusqu'à négativation, <span class=\"kw-alerte\">grippe</span> jusqu'à amélioration.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Déclaration obl<span class=\"kw-chiffre\">iga</span>toire — Légionellose</h4>\n      <div class=\"callout callout-danger\">\n        🚨 <strong>La <span class=\"kw-alerte\">légionellose est une maladie à déclaration obligatoire (DO)</span></strong> auprès de l'<strong><span class=\"kw-def\">ARS</span></strong> (formulaire CERFA n° 12202) : <span class=\"kw-clinique\">signalement immédiat</span> dès suspicion (anonymat préservé via codification), puis <span class=\"kw-clinique\">notification écrite</span> après confirmation. Objectif : déclencher une <strong>enquête environnementale</strong> pour identifier la source contaminante et la traiter (chloration, <span class=\"kw-alerte\">choc</span> thermique).\n      </div>\n\n      <p><strong>Autres pathogènes à <span class=\"kw-def\">DO</span></strong> dans le champ <span class=\"kw-etio\">infectieux</span> respiratoire : <span class=\"kw-alerte\">tuberculose</span> (cf. item 159), <span class=\"kw-alerte\">diphtérie</span>, <span class=\"kw-alerte\">infection invasive à méningocoque</span> (rare en pneumo mais pneumonie possible).</p>\n\n      <div class=\"callout callout-warn\">\n        ⚠️ <strong>Piège EDN :</strong> la <span class=\"kw-alerte\">légionellose</span> n'est <strong>pas une infection transmissible d'homme à homme</strong> (contamination par aérosols environnementaux uniquement) : pas d'éviction, pas de prophylaxie de l'entourage, pas d'<span class=\"kw-ttt\">antibioprophylaxie</span> post-exposition.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Bronchite aiguë</strong></p><ul><li>pas d’<span class=\"kw-alerte\">urgence</span>, <span class=\"kw-clinique\">évolution</span> spontanément favorable (<span class=\"kw-clinique\">apyrexie</span> en <span class=\"kw-chiffre\">~3 j</span>, <span class=\"kw-clinique\">toux post-infectieuse</span> jusqu’à <span class=\"kw-chiffre\">3 semaines</span>)</li></ul><p><strong><span class=\"kw-clinique\">PAC</span> <span class=\"q\">— gravité</span></strong></p><ul><li>1<sup>re</sup> cause de décès par infection dans <span class=\"kw-clinique\">les</span> pays occidentaux (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">2-5 %</span> ; jusqu’à <span class=\"kw-chiffre\">40 %</span> en réa ou chez l’<span class=\"kw-etio\">âgé institutionnalisé</span>)</li></ul><p><strong>ATB</strong></p><ul><li>urgente, idéalement après <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">prélèvements microbiologiques</span> (mais <span class=\"kw-ci\">ne jamais</span> la retarder)</li><li>en ambulatoire, pas de documentation préalable</li></ul><p><strong>Délai clé</strong></p><ul><li><span class=\"kw-def\">réévaluation</span> clinique <strong>obl<span class=\"kw-chiffre\">iga</span>toire à <span class=\"kw-chiffre\">48-72 h</span></strong>, quel que soit le lieu de prise en charge</li></ul>","hospit":"<p><strong>CRB-65 (clinique seul) :</strong> <span class=\"kw-clinique\">Confusion</span> ; Respiration <span class=\"kw-chiffre\">FR ≥ 30/min</span> ; Blood pressure <span class=\"kw-chiffre\">PAS &lt; 90</span> ou <span class=\"kw-chiffre\">PAD ≤ 60</span> ; <span class=\"kw-chiffre\">âge ≥ 65 ans</span>. Utilisable <em>seulement une fois la <span class=\"kw-def\">PAC</span> confirmée par la <span class=\"kw-imagerie\">RXT</span></em>.<br><strong>Ambulatoire :</strong> <span class=\"kw-chiffre\">CRB-65 = 0</span> et <span class=\"kw-def\">terrain</span> favorable (<span class=\"kw-chiffre\">âge &lt; 65 ans</span> avec <span class=\"kw-chiffre\">≤ 1 FR</span>, ou <span class=\"kw-chiffre\">&gt; 65 ans</span> sans FR).<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-alerte\">signe de gravité</span>, OU <span class=\"kw-chiffre\">≥ 2</span> <span class=\"kw-etio\">facteurs de risque</span>, OU (≥ 1 FR + <span class=\"kw-chiffre\">âge &gt; 65 ans</span>).<br><strong><span class=\"kw-alerte\">Réanimation</span> / USI :</strong> 1 <span class=\"kw-def\">critère majeur</span> (<span class=\"kw-alerte\">choc</span> nécessitant <span class=\"kw-ttt\">vasopresseurs</span>, <span class=\"kw-alerte\">IRA</span> nécessitant <span class=\"kw-ttt\">intubation</span>) OU <span class=\"kw-chiffre\">≥ 3</span> <span class=\"kw-def\">critères mineurs</span>.<br><strong>Règle d’or :</strong> le bon sens clinique prévaut ; en cas de doute, hospitalisation courte de <span class=\"kw-def\">surveillance</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Altération de la conscience</span> / <span class=\"kw-alerte\">confusion</span></li><li><span class=\"kw-alerte\">FR ≥ 30/min</span> ou <span class=\"kw-alerte\">signes de détresse respiratoire</span></li><li><span class=\"kw-alerte\">PAS &lt; 90 mmHg</span> ou <span class=\"kw-alerte\">PAD ≤ 60 mmHg</span> ou <span class=\"kw-alerte\">marbrures</span></li><li><span class=\"kw-alerte\">FC &gt; 120 bpm</span></li><li>Température <span class=\"kw-alerte\">&lt; 36 °C</span> ou <span class=\"kw-alerte\">&gt; 40 °C</span></li><li><span class=\"kw-alerte\">Cyanose</span>, <span class=\"kw-alerte\">tirage</span>, <span class=\"kw-alerte\">SpO₂ &lt; 90 %</span> sous oxygène</li><li><span class=\"kw-imagerie\">RXT</span> : <span class=\"kw-alerte\">atteinte bilatérale / multilobaire</span> ou <span class=\"kw-alerte\">extension rapide</span></li><li><span class=\"kw-alerte\">Défaillance d’organe</span> : <span class=\"kw-alerte\">insuffisance rénale ou hépatique</span>, <span class=\"kw-alerte\">CIVD</span>, <span class=\"kw-alerte\">thrombopénie</span>, <span class=\"kw-alerte\">hyperlactatémie</span></li></ul>","principes":"<p><strong>Bronchite aiguë :</strong> traitement symptomatique seul — <strong><span class=\"kw-ci\">pas d’ATB</span>, <span class=\"kw-ci\">pas d’AINS</span>, <span class=\"kw-ci\">pas d’antitussif</span>, <span class=\"kw-ci\">pas de corticoïde</span></strong>.<br><strong><span class=\"kw-clinique\">PAC</span> :</strong> l’<span class=\"kw-ttt\">ATB probabiliste</span> doit <strong>toujours couvrir le <span class=\"kw-etio\">pneumocoque</span></strong> (sauf sujet jeune ambulatoire évoquant une <span class=\"kw-etio\">bactérie atypique</span>).</p><ul><li><span class=\"kw-ttt\">Amoxicilline</span> = molécule de 1<sup>re</sup> ligne du <span class=\"kw-etio\">pneumocoque</span> (<span class=\"kw-def\">PSDP</span> : fortes doses, le <span class=\"kw-ttt\">clavulanate</span> est inutile)</li><li><span class=\"kw-etio\">Bactéries atypiques</span> / <span class=\"kw-def\">légionellose</span> : <span class=\"kw-ttt\">macrolide</span> (alternative <span class=\"kw-ttt\">FQAP</span>)</li><li>Durée : <span class=\"kw-chiffre\">7 j</span> pour une <span class=\"kw-def\">PAC</span> tout-venant ; <span class=\"kw-chiffre\">8-14 j</span> si <span class=\"kw-etio\">atypique/légionelle</span> ; <span class=\"kw-chiffre\">21 j</span> si <span class=\"kw-alerte\">légionellose grave</span> ou <span class=\"kw-etio\">immunodéprimé</span></li><li><span class=\"kw-ttt\">Oxygénothérapie</span> (corr<span class=\"kw-chiffre\">ige</span> le <span class=\"kw-def\">shunt</span>) ; <span class=\"kw-ttt\">kinésithérapie de drainage bronchique</span> systématique</li><li>Période grippale chez l’hospitalisé : ajouter <span class=\"kw-ttt\">oseltamivir</span> <span class=\"kw-chiffre\">5 j</span> (sans dispenser de l’<span class=\"kw-ttt\">ATB</span>)</li><li><span class=\"kw-ttt\">Corticothérapie systémique</span> : bénéfice non démontré → non recommandée</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Réévaluation</span> à<span class=\"kw-chiffre\"> 48-72 h</span> :</strong> systématique ; l’amélioration attendue <em>n’impose pas l’<span class=\"kw-clinique\">apyrexie</span> stricte</em> (<span class=\"kw-clinique\">fièvre</span> parfois prolongée <span class=\"kw-chiffre\">5 j</span> avec <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">intracellulaires</span>).<br><strong><span class=\"kw-clinique\">Évolution</span> défavorable :</strong> chercher une cause d’échec — <span class=\"kw-alerte\">pneumonie compliquée</span> (<span class=\"kw-alerte\">épanchement</span>, <span class=\"kw-alerte\">abcès</span>, <span class=\"kw-alerte\">excavation</span>), <span class=\"kw-etio\">germe hors spectre</span>, mauvaise observance, ou erreur diagnostique (<span class=\"kw-def\">embolie pulmonaire</span>, <span class=\"kw-def\">tuberculose</span>, <span class=\"kw-def\">cancer bronchique</span>).<br><strong>À distance :</strong> <span class=\"kw-imagerie\">RXT</span> de contrôle chez le <span class=\"kw-etio\">fumeur</span> / sujet <span class=\"kw-chiffre\">&gt; 50 ans</span> (dépister un <span class=\"kw-def\">cancer bronchique</span> sous-jacent).<br><strong>Prévention :</strong> <span class=\"kw-ttt\">vaccination antipneumococcique</span> (<span class=\"kw-ttt\">VPC13</span> puis <span class=\"kw-ttt\">VPP23</span>) + <span class=\"kw-ttt\">antigrippale</span> chez les terrains à risque ; mesures d’hygiène en collectivité.</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/pneumonies-aigues-communautaires","label":"Collège Pédiatrie — Pneumonies aiguës communautaires"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/bronchiolite-aigue-du-nourrisson","label":"Collège Pédiatrie — Bronchiolite aiguë du nourrisson"},{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_154_INFECTIONS_RESPIRATOIRES_2023.pdf","label":"Collège CEP — Infections respiratoires (PDF item 154)"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-154.pdf","label":"Collège Pilly — Infections respiratoires (item 154, PDF)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/24.%20Pneumonie%20aigu%C3%AB%20communautaire%20grave.pdf","label":"Collège CE-MIR — Pneumonie aiguë communautaire grave (PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Infection respiratoire basse suspectée — Adulte — tri clinique initial","detail":"<h4>CAT — infection respiratoire basse de l’adulte — Orientation (ambu / hospit / réa) + <span class=\"kw-ttt\">antibiothérapie</span> probabiliste</h4>","branches":[{"to":"t-bronchite","label":"Pas de foyer (auscultation normale ou râles bronchiques), pas de polypnée","color":"green"},{"to":"q-gravite","label":"Foyer de crépitants → RXT confirme une PAC","color":"amber"}]},{"id":"t-bronchite","kind":"terminal","label":"Bronchite aiguë → ambulatoire","color":"green","detail":"<h4>Arguments</h4><ul><li><span class=\"kw-etio\">Virale</span> dans <span class=\"kw-chiffre\">90 %</span> des cas</li><li><span class=\"kw-clinique\">Toux</span> ± <span class=\"kw-clinique\">douleur rétro-sternale</span>, pas de <span class=\"kw-clinique\">crépitant en foyer</span></li><li>Aucun examen complémentaire (<span class=\"kw-imagerie\">RXT</span> seulement si doute sur une <span class=\"kw-def\">PAC</span>)</li></ul><h4>Traitement</h4><ul><li>Symptomatique : <span class=\"kw-ttt\">paracétamol</span></li><li><span class=\"kw-ci\">PAS d’antibiotique</span>, <span class=\"kw-ci\">PAS d’AINS</span>, <span class=\"kw-ci\">PAS d’antitussif</span>, <span class=\"kw-ci\">PAS de corticoïde</span></li></ul><h4><span class=\"kw-clinique\">Évolution</span></h4><ul><li>Favorable : <span class=\"kw-clinique\">fièvre</span>/<span class=\"kw-clinique\">signes respi</span> en <span class=\"kw-chiffre\">~3 j</span>, <span class=\"kw-clinique\">toux post-infectieuse</span> jusqu’à <span class=\"kw-chiffre\">3 semaines</span>. Si persistance → reconsidérer le diagnostic.</li></ul>"},{"id":"q-gravite","kind":"decision","label":"Signe(s) de gravité ? — CRB-65 ≥ 1, détresse respiratoire, choc, défaillance d’organe","branches":[{"to":"q-rea","label":"Oui — au moins un signe de gravité","color":"red"},{"to":"q-terrain","label":"Non — CRB-65 = 0, pas de signe de gravité","color":"green"}]},{"id":"q-rea","kind":"decision","label":"Critère de réanimation ? — 1 critère majeur OU ≥ 3 critères mineurs","branches":[{"to":"t-rea","label":"Critère majeur (choc/vasopresseurs ou IRA/intubation) ou ≥ 3 mineurs","color":"red"},{"to":"t-hospit-grav","label":"Non — gravité sans critère de réa","color":"amber"}]},{"id":"t-rea","kind":"terminal","label":"Réanimation / soins intensifs","color":"red","detail":"<h4>Cibles</h4><ul><li>Couvrir <span class=\"kw-etio\">pneumocoque</span> ET <span class=\"kw-etio\">legionella</span>.</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">C3G IV</span> (<span class=\"kw-ttt\">céfotaxime</span>/<span class=\"kw-ttt\">ceftriaxone</span>) + <span class=\"kw-ttt\">macrolide IV</span></li><li>OU <span class=\"kw-ttt\">C3G IV</span> + <span class=\"kw-ttt\">lévofloxacine IV</span></li></ul><h4>Si FR de P. aeruginosa</h4><ul><li><span class=\"kw-ttt\">Trithérapie</span> : <span class=\"kw-ttt\">β-lactamine antipyocyanique</span> (<span class=\"kw-ttt\">céfépime</span> / <span class=\"kw-ttt\">pipéracilline-tazobactam</span> / <span class=\"kw-ttt\">carbapénème</span>) + <span class=\"kw-ttt\">amikacine</span> (<span class=\"kw-chiffre\">3-5 j</span>) + <span class=\"kw-ttt\">macrolide IV</span> ou <span class=\"kw-ttt\">lévofloxacine</span>.</li></ul><h4>Support</h4><ul><li><span class=\"kw-ttt\">O₂</span> ± <span class=\"kw-ttt\">OHD</span>/<span class=\"kw-ttt\">intubation</span> si <span class=\"kw-alerte\">hypoxémie réfractaire</span></li><li><span class=\"kw-ttt\">Remplissage</span> <span class=\"kw-chiffre\">30 mL/kg</span> <span class=\"kw-ttt\">NaCl 0,9 %</span> ± <span class=\"kw-ttt\">noradrénaline</span></li><li>Renvois : 158 · 209</li></ul>"},{"id":"t-hospit-grav","kind":"terminal","label":"Hospitalisation conventionnelle","color":"amber","detail":"<h4>Bilan</h4><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">iono</span>, <span class=\"kw-bio\">créat</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">coagulation</span></li><li><span class=\"kw-bio\">Hémocultures</span>, <span class=\"kw-bio\">ECBC</span>, ± <span class=\"kw-bio\">antigénurie légionelle</span>, <span class=\"kw-bio\">PCR nasopharyngée</span> en période épidémique</li><li><span class=\"kw-def\">Dépistage</span> <span class=\"kw-def\">VIH</span> systématiquement proposé</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-etio\">Pneumocoque</span> suspecté/documenté : <span class=\"kw-ttt\">amoxicilline</span></li><li><span class=\"kw-etio\">Sujet âgé</span> / <span class=\"kw-etio\">comorbidité</span> : <span class=\"kw-ttt\">amox-ac. clavulanique</span> OU <span class=\"kw-ttt\">C3G inj.</span> OU <span class=\"kw-ttt\">FQAP</span> (<span class=\"kw-ttt\">lévofloxacine</span>)</li></ul><h4>Renvois</h4><ul><li>177 (anti-<span class=\"kw-etio\">infectieux</span>) · 206 (épanchement) · 169 (<span class=\"kw-etio\">VIH</span>)</li></ul>"},{"id":"q-terrain","kind":"decision","label":"Le terrain impose-t-il l’hospitalisation ? — ≥ 2 facteurs de risque, ou ≥ 1 FR + âge > 65 ans","branches":[{"to":"t-hospit-terrain","label":"Oui — terrain à risque","color":"amber"},{"to":"q-comorbidite","label":"Non — ambulatoire possible","color":"green"}]},{"id":"t-hospit-terrain","kind":"terminal","label":"Hospitalisation conventionnelle (terrain)","color":"amber","detail":"<h4>Pourquoi</h4><ul><li>FR : <span class=\"kw-chiffre\">âge ≥ 65 ans</span>, <span class=\"kw-def\">comorbidités</span> (<span class=\"kw-etio\">insuffisance cardiaque/rénale/hépatique</span>, <span class=\"kw-etio\">BPCO</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">néoplasie</span>, <span class=\"kw-etio\">immunodépression</span>…), <span class=\"kw-etio\">ATCD de pneumonie</span>, <span class=\"kw-alerte\">hospitalisation</span> dans l’année, <span class=\"kw-etio\">vie en institution</span>, <span class=\"kw-def\">isolement</span> social.</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">Amox-ac. clavulanique</span> OU <span class=\"kw-ttt\">C3G inj.</span> OU <span class=\"kw-ttt\">FQAP</span></li><li>Si <span class=\"kw-etio\">pneumocoque</span> documenté : <span class=\"kw-ttt\">amoxicilline</span></li></ul>"},{"id":"q-comorbidite","kind":"decision","label":"Comorbidité / sujet âgé / éthylique ?","branches":[{"to":"t-ambu-sain","label":"Non — sujet sain","color":"green"},{"to":"t-ambu-risque","label":"Oui — comorbidité / âgé / éthylique","color":"amber"}]},{"id":"t-ambu-sain","kind":"terminal","label":"PAC ambulatoire — sujet sain","color":"green","detail":"<h4>ATB de 1re intention</h4><ul><li><span class=\"kw-ttt\">Amoxicilline</span> (cible <span class=\"kw-etio\">pneumocoque</span>)</li><li>OU <span class=\"kw-ttt\">macrolide</span> (si <span class=\"kw-etio\">bactérie atypique</span> évoquée chez le sujet jeune)</li><li>Alternative : <span class=\"kw-ttt\">pristinamycine</span></li></ul><h4>Échec à<span class=\"kw-chiffre\"> 48-72 h</span></h4><ul><li>Switch entre <span class=\"kw-ttt\">amoxicilline</span> et <span class=\"kw-ttt\">macrolide</span> ; si <span class=\"kw-alerte\">aggravation rapide</span> → <span class=\"kw-alerte\">hospitalisation</span>.</li></ul><h4>Durée</h4><ul><li><span class=\"kw-chiffre\">7 jours</span>.</li></ul>"},{"id":"t-ambu-risque","kind":"terminal","label":"PAC ambulatoire — sujet à risque","color":"amber","detail":"<h4>ATB de 1re intention</h4><ul><li><span class=\"kw-ttt\">Amox-ac. clavulanique</span></li><li>OU <span class=\"kw-ttt\">C3G injectable</span> (<span class=\"kw-ttt\">céfotaxime</span>/<span class=\"kw-ttt\">ceftriaxone</span>)</li><li>OU <span class=\"kw-ttt\">FQAP</span> (<span class=\"kw-ttt\">lévofloxacine</span>)</li></ul><h4>Échec à<span class=\"kw-chiffre\"> 48-72 h</span></h4><ul><li>Ajout d’un <span class=\"kw-ttt\">macrolide</span> (ou <span class=\"kw-ttt\">C3G</span> + <span class=\"kw-ttt\">macrolide</span>) ; le plus souvent <span class=\"kw-alerte\">hospitalisation</span>.</li></ul><h4><span class=\"kw-def\">Réévaluation</span></h4><ul><li>Clinique obl<span class=\"kw-chiffre\">iga</span>toire à <span class=\"kw-chiffre\">48-72 h</span>, capable de joindre un médecin si <span class=\"kw-alerte\">dégradation</span>.</li></ul>"}]},"cards":[{"i":"4e8315206fde","n":154,"o":"154-11","u":"Contenu multimédia","t":"Radiographie de thorax avec pneumopathie franche lobaire aiguë (PFLA)","q":"Quels sont les signes radiologiques caractéristiques et différentiels de la PFLA sur une radiographie de thorax ?","a":"<ul><li><strong>Bronchogramme aérien</strong> visible au sein de l'opacité (signe clé différenciant d'une atélectasie).</li><li><strong>Absence de rétraction</strong> du parenchyme (différenciant d'une atélectasie obstructive).</li><li>Absence, le plus souvent, d'épanchement initial.</li></ul>"},{"i":"5a3075cccdb3","n":154,"o":"154-11","u":"Contenu multimédia","t":"Radiographie de thorax avec pneumopathie franche lobaire aiguë (PFLA)","q":"Quelle définition radiologique est donnée pour la pneumopathie franche lobaire aiguë (PFLA) sur une radiographie de thorax ?","a":"<p>La pneumopathie franche lobaire aiguë (PFLA) est une <strong>opacité alvéolaire</strong> de densité <strong>homogène</strong> et d'aspect <strong>systématisé</strong>, occupant un segment ou un lobe entier, avec des <strong>limites nettes</strong> (par exemple, un bord scissural rectiligne).</p>"},{"i":"fbb0c7540e21","n":154,"o":"154-11","u":"Contenu multimédia","t":"Radiographie de thorax avec pneumopathie franche lobaire aiguë (PFLA)","q":"Quels sont les signes cliniques classiques associés à une pneumopathie franche lobaire aiguë (PFLA) justifiant une corrélation à l'imagerie ?","a":"<p>Cliniquement, la PFLA est souvent corrélée à :</p><ul><li>Un <strong>foyer de crépitants</strong> localisé.</li><li>Un <strong>souffle tubaire</strong>.</li><li>Une <strong>matité</strong> en regard.</li><li>Un tableau associant un <strong>début brutal</strong>, une <strong>fièvre à 39-40 °C</strong>, un <strong>point de côté thoracique</strong> et une <strong>expectoration rouille</strong>.</li></ul>"},{"i":"27bfb9a3b3e4","n":154,"o":"154-12","u":"Contenu multimédia","t":"Radiographie thoracique de face : pleuropneumopathie de l'enfant","q":"Quels sont les critères d'empyème pleural (pleurésie purulente) chez l'enfant ?","a":"<p>Les critères d'empyème pleural sont le <strong>pus franc à la ponction</strong> ou un <strong>pH &lt; 7,2</strong> ou un <strong>glucose &lt; 2,2 mmol/L</strong> ou des <strong>LDH élevés</strong> ou la présence d'un <strong>germe au Gram/culture</strong>.</p>"},{"i":"471c751e41f3","n":154,"o":"154-12","u":"Contenu multimédia","t":"Radiographie thoracique de face : pleuropneumopathie de l'enfant","q":"Comment se définit une pleuropneumopathie de l'enfant ?","a":"<p>La pleuropneumopathie de l'enfant de l'enfant associe une <strong>condensation parenchymateuse</strong> et un <strong>épanchement pleural homolatéral</strong>.</p>"},{"i":"4fe60c82bb49","n":154,"o":"154-12","u":"Contenu multimédia","t":"Radiographie thoracique de face : pleuropneumopathie de l'enfant","q":"Quelle est l'étiologie la plus fréquente d'une pleuropneumopathie de l'enfant ?","a":"<p>Elle survient majoritairement en complication d'une Pneumopathie Aiguë Communautaire (PAC) à <strong>pneumocoque</strong>, parfois <em>Staphylococcus aureus</em>.</p>"},{"i":"c0b43c31edd5","n":154,"o":"154-12","u":"Contenu multimédia","t":"Radiographie thoracique de face : pleuropneumopathie de l'enfant","q":"Quelle est la prise en charge d'un empyème pleural chez l'enfant ?","a":"<p>L'empyème pleural impose un <strong>drainage thoracique</strong> en plus d'une <strong>antibiothérapie prolongée</strong>.</p>"},{"i":"e5b37c8eb7ed","n":154,"o":"154-12","u":"Contenu multimédia","t":"Radiographie thoracique de face : pleuropneumopathie de l'enfant","q":"Quels sont les signes radiologiques d'une pleuropneumopathie de l'enfant sur une radiographie thoracique de face ?","a":"<ul><li><strong>Opacité du foyer pneumonique</strong> : condensation alvéolaire systématisée, homogène, avec bronchogramme aérien.</li><li><strong>Opacité pleurale</strong> : dense, à limite supérieure concave en haut et en dehors (ligne de Damoiseau-Ellis), homogène, masquant le diaphragme.</li><li><strong>Effacement du cul-de-sac pleural</strong> : comblement du sinus costo-diaphragmatique latéral ; effacement de la coupole diaphragmatique homolatérale.</li><li><strong>Déviation médiastinale</strong> : vers le côté controlatéral si épanchement abondant.</li><li><strong>Scoliose antalgique</strong> : concavité homolatérale possible.</li></ul>"},{"i":"0653270da1a1","n":154,"o":"154-13","u":"Prise en charge","t":"Connaître les principes du traitement de première intention des infections respiratoires basses chez l'adulte et l'enfant","q":"Quel est le traitement probabiliste de première intention d'une PAC chez un adulte ambulatoire sain sans gravité ?","a":"<ul><li><strong>Molécule :</strong> <strong>amoxicilline 1 g × 3/j</strong> par voie orale.</li><li><strong>Alternative :</strong> macrolide si suspicion d'atypique ou pristinamycine par voie orale.</li><li><strong>Durée :</strong> <strong>7 jours</strong>.</li><li>Une réévaluation à 48-72h est indispensable. En cas d'aggravation rapide, une hospitalisation est nécessaire.</li></ul>"},{"i":"0a45fd0372bc","n":154,"o":"154-13","u":"Prise en charge","t":"Connaître les principes du traitement de première intention des infections respiratoires basses chez l'adulte et l'enfant","q":"Quelle est la durée totale de l'antibiothérapie pour une PAC ?","a":"<ul><li><strong>7 jours</strong> pour la PAC « tout venant ».</li><li><strong>8 à 14 jours</strong> pour les germes atypiques ou la légionellose non grave.</li><li><strong>21 jours</strong> pour une légionellose grave ou chez un patient immunodéprimé.</li></ul><p>Une réévaluation clinique est <strong>obligatoire à 48-72h</strong>.</p>"},{"i":"0acfa89f30f2","n":154,"o":"154-13","u":"Prise en charge","t":"Connaître les principes du traitement de première intention des infections respiratoires basses chez l'adulte et l'enfant","q":"Quelle est l'approche générale de l'antibiothérapie pour une Pneumonie Communautaire (PAC) et quelle bactérie doit-elle toujours couvrir en première intention ?","a":"<p>L'antibiothérapie probabiliste d'une PAC est <strong>urgente</strong>. Elle doit toujours couvrir le <strong>pneumocoque</strong>, sauf rares cas évocateurs de bactérie atypique chez le sujet jeune en ambulatoire.</p>"},{"i":"9ecf562a62c6","n":154,"o":"154-13","u":"Prise en charge","t":"Connaître les principes du traitement de première intention des infections respiratoires basses chez l'adulte et l'enfant","q":"Quels sont les traitements associés à considérer en cas d'hospitalisation pour une PAC ?","a":"<ul><li><strong>Oxygénothérapie</strong> pour corriger l'hypoxémie de shunt.</li><li><strong>Remplissage vasculaire</strong> par NaCl 0,9 % à 30 mL/kg (± noradrénaline si hypotension persistante).</li><li><strong>Kinésithérapie de drainage bronchique</strong> systématique.</li><li><strong>Oseltamivir</strong> en cas de suspicion de grippe en période épidémique (75 mg × 2/j PO × 5 jours chez l'adulte).</li></ul><p>La ventilation non invasive (VNI) et la corticothérapie systémique ne sont pas démontrées comme utiles dans la PAC.</p>"},{"i":"b70b010b93e5","n":154,"o":"154-13","u":"Prise en charge","t":"Connaître les principes du traitement de première intention des infections respiratoires basses chez l'adulte et l'enfant","q":"Quelle est la prise en charge d'une bronchiolite aiguë chez le nourrisson (< 12 mois) ?","a":"<p>Il n'y a <strong>pas d'antibiothérapie</strong> ni de traitement spécifique efficace recommandé. La prise en charge est <strong>symptomatique</strong> et repose sur :</p><ul><li>Désobstruction rhinopharyngée (DRP).</li><li>Fractionnement de l'alimentation.</li><li>En cas d'hospitalisation : oxygénothérapie, support nutritionnel (entéral ou hydratation IV), et support ventilatoire (lunettes haut débit ou CPAP) si aggravation sous oxygène.</li></ul><p>Les bronchodilatateurs, corticoïdes et kinésithérapie de drainage ne sont pas recommandés en routine.</p>"},{"i":"c29994803fd6","n":154,"o":"154-13","u":"Prise en charge","t":"Connaître les principes du traitement de première intention des infections respiratoires basses chez l'adulte et l'enfant","q":"Quel est le traitement probabiliste de première intention d'une PAC chez l'enfant ?","a":"<ul><li><strong>Molécule :</strong> <strong>amoxicilline par voie orale à 80-100 mg/kg/j</strong> en 3 prises (maximum 3 g/j), ciblant le pneumocoque.</li><li><strong>Durée :</strong> <strong>5 jours</strong>.</li><li>En cas de suspicion de Mycoplasme (> 3 ans), un macrolide est indiqué.</li><li>En cas d'allergie à la pénicilline, une C3G injectable peut être utilisée. La pristinamycine est possible après 6 ans.</li></ul>"},{"i":"d5edce97820e","n":154,"o":"154-13","u":"Prise en charge","t":"Connaître les principes du traitement de première intention des infections respiratoires basses chez l'adulte et l'enfant","q":"Quelle est l'antibiothérapie probabiliste d'une PAC chez un adulte hospitalisé en service conventionnel avec pneumocoque suspecté ou documenté ?","a":"<ul><li><strong>Molécule :</strong> <strong>amoxicilline par voie orale ou intraveineuse</strong>.</li><li>Un switch oral est possible à J3 si apyrexie ≥ 24h et stabilité clinique.</li><li>Un ajout de macrolide est à considérer en cas de suspicion d'atypique.</li></ul>"},{"i":"1772a68a7b78","n":154,"o":"154-14","u":"Prise en charge","t":"Connaître les principes du traitement de la bronchite aiguë (pas d'antibiothérapie, pas d'anti-inflammatoires non stéroïdiens (AINS), pas d'anti-tussifs)","q":"Pourquoi les anti-tussifs ne sont-ils pas recommandés dans la prise en charge de la bronchite aiguë ?","a":"<p>Les anti-tussifs ne sont pas recommandés car ils augmentent le risque d'<strong>encombrement bronchique</strong> et de <strong>surinfection</strong>.</p>"},{"i":"49ba79b2204a","n":154,"o":"154-14","u":"Prise en charge","t":"Connaître les principes du traitement de la bronchite aiguë (pas d'antibiothérapie, pas d'anti-inflammatoires non stéroïdiens (AINS), pas d'anti-tussifs)","q":"Outre les antibiotiques, AINS et anti-tussifs, quels autres traitements ne sont pas recommandés pour la bronchite aiguë et pourquoi ?","a":"<ul><li><strong>Corticoïdes systémiques ou inhalés</strong> : Inefficaces et potentiellement délétères.</li><li><strong>Mucolytiques</strong> et <strong>expectorants</strong> : Potentiellement délétères.</li></ul>"},{"i":"60a53908ac51","n":154,"o":"154-14","u":"Prise en charge","t":"Connaître les principes du traitement de la bronchite aiguë (pas d'antibiothérapie, pas d'anti-inflammatoires non stéroïdiens (AINS), pas d'anti-tussifs)","q":"Quelle est l'approche thérapeutique principale de la bronchite aiguë non compliquée de l'adulte sain, compte tenu de son étiologie prédominante ?","a":"<p>La bronchite aiguë de l'adulte sain étant virale dans <strong>90 %</strong> des cas, le traitement est <strong>exclusivement symptomatique et ambulatoire</strong>.</p>"},{"i":"9aecc1261334","n":154,"o":"154-14","u":"Prise en charge","t":"Connaître les principes du traitement de la bronchite aiguë (pas d'antibiothérapie, pas d'anti-inflammatoires non stéroïdiens (AINS), pas d'anti-tussifs)","q":"Pourquoi les antibiotiques ne sont-ils pas recommandés dans le traitement de la bronchite aiguë de l'adulte sain, y compris en cas de BPCO stable ?","a":"<ul><li>L'origine est majoritairement <strong>virale</strong>, rendant les antibiotiques inefficaces.</li><li>Ils favorisent l'émergence de la <strong>résistance bactérienne</strong>.</li></ul>"},{"i":"f857d7f7e42e","n":154,"o":"154-14","u":"Prise en charge","t":"Connaître les principes du traitement de la bronchite aiguë (pas d'antibiothérapie, pas d'anti-inflammatoires non stéroïdiens (AINS), pas d'anti-tussifs)","q":"Quels sont les risques associés à l'utilisation des anti-inflammatoires non stéroïdiens (AINS) en cas de bronchite aiguë ?","a":"<p>L'utilisation des AINS est <strong>contre-indiquée</strong> en raison d'un risque démontré de <strong>surinfection cutanée</strong> et de <strong>complications pleurales</strong>, telles que l'empyème, en cas de bascule vers une pneumonie communautaire (PAC).</p>"},{"i":"00823916f630","n":154,"o":"154-17","u":"Prévention","t":"Connaître les principaux terrains à risque de pneumonie et les principes de la prévention vaccinale","q":"Quels sont les deux principaux vaccins recommandés dans la prévention des infections bronchopulmonaires communautaires ?","a":"<p>La prévention vaccinale de la pneumonie aiguë communautaire (PAC) repose sur deux vaccins :</p><ul><li>Le <strong>vaccin antigrippal annuel</strong>.</li><li>Le <strong>vaccin antipneumococcique séquentiel</strong> (initialement le <strong>VPC13</strong>, puis le <strong>VPP23</strong>).</li></ul>"},{"i":"41fe16f641ad","n":154,"o":"154-17","u":"Prévention","t":"Connaître les principaux terrains à risque de pneumonie et les principes de la prévention vaccinale","q":"Quels sont les principaux terrains à risque justifiant la vaccination antipneumococcique et antigrippale chez l'adulte ?","a":"<p>Les principaux terrains à risque justifiant la vaccination sont :</p><ul><li>L'<strong>âge ≥ 65 ans</strong>.</li><li>Les pathologies pulmonaires chroniques : <strong>BPCO</strong>, <strong>asthme sévère</strong>, insuffisance respiratoire chronique (IRC) respiratoire, <strong>emphysème</strong>.</li><li>Les pathologies cardiovasculaires : <strong>insuffisance cardiaque</strong>, cardiopathie congénitale cyanogène, <strong>coronaropathie</strong>, accident vasculaire cérébral (AVC).</li><li>Les pathologies métaboliques, néphrologiques ou hépatiques : <strong>diabète mal équilibré</strong>, IRC, <strong>syndrome néphrotique</strong>, <strong>hépatopathie chronique</strong>.</li><li>Les <strong>immunodéprimés</strong> : asplénie/splénectomie, drépanocytose, VIH, greffe, chimiothérapie, biothérapie, corticothérapie prolongée.</li><li>La présence d'une <strong>brèche ostéo-méningée</strong> ou d'<strong>implants cochléaires</strong>.</li></ul><p>Un cas particulier est le <strong>nourrisson</strong> pour le vaccin VPC13 (obligatoire).</p>"},{"i":"818ff0285010","n":154,"o":"154-17","u":"Prévention","t":"Connaître les principaux terrains à risque de pneumonie et les principes de la prévention vaccinale","q":"Quel est le schéma vaccinal antipneumococcique recommandé chez l'adulte à risque n'ayant jamais été vacciné ?","a":"<p>Le schéma vaccinal antipneumococcique recommandé chez l'adulte à risque naïf de vaccination est le suivant :</p><ul><li>Administration d'<strong>une dose de VPC13</strong> (vaccin conjugué).</li><li>Puis administration d'<strong>une dose de VPP23</strong> (vaccin polysaccharidique) <strong>au moins 2 mois plus tard</strong>. Ce délai est crucial pour éviter une hyporéactivité.</li><li>Un rappel par VPP23 peut être envisagé <strong>à ≥ 5 ans</strong> si le risque persiste.</li></ul><p>La co-administration avec le vaccin antigrippal est possible.</p>"},{"i":"3ec6b9d31341","n":154,"o":"154-18","u":"Prévention","t":"Connaître les mesures d'hygiène à adopter en collectivité","q":"Quand l'éviction temporaire d'une collectivité est-elle nécessaire pour prévenir la transmission de certaines infections bronchopulmonaires ?","a":"<p>L'éviction temporaire dépend du germe :</p><ul><li>Pour la <strong>coqueluche</strong> : jusqu'à <strong>5 jours d'antibiothérapie</strong>.</li><li>Pour la <strong>tuberculose pulmonaire bacillifère</strong> : jusqu'à la <strong>négativation</strong> des examens bactériologiques.</li><li>Pour la <strong>grippe</strong> : jusqu'à l'<strong>amélioration</strong> clinique des symptômes.</li></ul>"},{"i":"4a4a5d44c95e","n":154,"o":"154-18","u":"Prévention","t":"Connaître les mesures d'hygiène à adopter en collectivité","q":"Quelles sont les mesures générales d'hygiène à adopter en collectivité pour prévenir les infections bronchopulmonaires communautaires (hors vaccination) ?","a":"<p>Ces mesures incluent :</p><ul><li>Une <strong>hygiène des mains rigoureuse</strong> (lavage au savon ou solution hydro-alcoolique), en particulier en milieu de soins ou en période épidémique.</li><li>Une <strong>hygiène respiratoire</strong> (utilisation de mouchoirs à usage unique, port d'un masque chirurgical si toux fébrile, maintien d'une distance physique).</li><li>Le <strong>sevrage tabagique</strong> systématiquement proposé, car le tabac est un facteur de risque majeur.</li><li>Une <strong>hygiène bucco-dentaire</strong>, primordiale pour prévenir les pneumonies d'inhalation, notamment chez les sujets âgés et institutionnalisés.</li><li>L'<strong>entretien des installations à risque de <em>Legionella</em></strong> (tours aéroréfrigérantes, ballons d'eau chaude > 50°C, spa, brumisateurs) sous la responsabilité du gestionnaire de l'établissement.</li></ul>"},{"i":"ecc7f0f76513","n":154,"o":"154-18","u":"Prévention","t":"Connaître les mesures d'hygiène à adopter en collectivité","q":"La légionellose nécessite-t-elle une éviction ou une prophylaxie de l'entourage en collectivité ?","a":"<p>Non. La légionellose n'est <strong>pas transmissible d'homme à homme</strong> et est contractée uniquement par inhalation d'aérosols environnementaux. Par conséquent, il n'y a pas lieu d'instaurer une éviction du patient malade ni une prophylaxie post-exposition pour son entourage.</p>"},{"i":"632e886c72cc","n":154,"o":"154-6","u":"Identifier une urgence","t":"Savoir rechercher et reconnaître les signes de gravité cliniques et paracliniques","q":"Quels sont les facteurs de gravité spécifiques à rechercher devant une infection bronchopulmonaire communautaire (PAC) chez l'enfant ?","a":"<p>Les facteurs de gravité spécifiques à rechercher chez l'enfant sont :</p><ul><li><strong>Terrain</strong> : âge <strong>&lt; 6 mois</strong>, comorbidités (cardiopathie, pathologie pulmonaire chronique, drépanocytose, immunosuppression).</li><li><strong>Respiratoire</strong> : FR très élevée pour l'âge, intensité des signes de lutte, <strong>cyanose</strong>, <strong>SpO₂ &lt; 95 %</strong> sous air.</li><li><strong>Général</strong> : aspect toxique, troubles hémodynamiques, sueurs, troubles de conscience, difficultés à s'alimenter.</li><li><strong>Radiologique</strong> : pneumonie très étendue (<strong>≥ 2 lobes</strong>), adénopathies intertrachéobronchiques.</li><li><strong>Complications locales</strong> : abcès, épanchement pleural.</li></ul>"},{"i":"64b3b80aaf8c","n":154,"o":"154-6","u":"Identifier une urgence","t":"Savoir rechercher et reconnaître les signes de gravité cliniques et paracliniques","q":"Quels sont les signes cliniques orientant vers une défaillance des fonctions vitales chez l'adulte atteint d'une infection bronchopulmonaire communautaire (PAC) ?","a":"<p>Les signes cliniques de défaillance des fonctions vitales devant une PAC incluent :</p><ul><li><strong>Conscience</strong> : altération, confusion, troubles de la vigilance.</li><li><strong>Fréquence respiratoire</strong> (FR) : <strong>≥ 30/min</strong>.</li><li><strong>Fréquence cardiaque</strong> (FC) : <strong>≥ 120 bpm</strong>.</li><li><strong>Pression artérielle</strong> (PA) : PAs <strong>&lt; 90 mmHg</strong> ou PAd <strong>≤ 60 mmHg</strong>, présence de marbrures.</li><li><strong>Température</strong> : <strong>&lt; 36 °C</strong> ou <strong>> 40 °C</strong>.</li><li><strong>SpO₂</strong> : hypoxémie nécessitant une supplémentation en oxygène.</li></ul>"},{"i":"6c6f46c37bed","n":154,"o":"154-6","u":"Identifier une urgence","t":"Savoir rechercher et reconnaître les signes de gravité cliniques et paracliniques","q":"Citez les principaux facteurs de risque chez l'adulte qui, associés à une infection bronchopulmonaire communautaire (PAC), recommandent une hospitalisation.","a":"<p>Les principaux facteurs de risque qui, associés à une PAC, recommandent une hospitalisation sont :</p><ul><li><strong>Âge ≥ 65 ans</strong>.</li><li><strong>Comorbidités</strong> : insuffisance cardiaque, maladie cérébrovasculaire, insuffisance rénale chronique (IRC), hépatopathie chronique, diabète mal équilibré, BPCO avec TVO, néoplasie évolutive, immunodépression, drépanocytose homozygote, splénectomie.</li><li><strong>Antécédents</strong> : pneumonie bactérienne, hospitalisation dans l'année, vie en institution.</li><li><strong>Facteurs aggravants</strong> : échec d'une antibiothérapie ambulatoire préalable, exposition récente aux AINS, pneumonie d'inhalation, pneumonie obstructive sur obstacle trachéo-bronchique.</li></ul>"},{"i":"f1723ff75680","n":154,"o":"154-6","u":"Identifier une urgence","t":"Savoir rechercher et reconnaître les signes de gravité cliniques et paracliniques","q":"Quels sont les critères du score CRB65 et à quoi sert-il pour l'évaluation d'une infection bronchopulmonaire communautaire (PAC) chez l'adulte ?","a":"<p>Le score CRB65 est un score clinique utilisé en ville pour l'orientation après diagnostic de PAC. Il comprend les critères suivants :</p><ul><li><strong>C</strong>onfusion mentale.</li><li><strong>R</strong>espiration : FR <strong>≥ 30/min</strong>.</li><li><strong>B</strong>lood pressure : PAs <strong>&lt; 90 mmHg</strong> ou PAd <strong>≤ 60 mmHg</strong>.</li><li><strong>65</strong> : âge <strong>≥ 65 ans</strong>.</li></ul><p>Une évaluation hospitalière est recommandée dès <strong>≥ 1 critère CRB65</strong>.</p>"},{"i":"f5e8719b63b0","n":154,"o":"154-6","u":"Identifier une urgence","t":"Savoir rechercher et reconnaître les signes de gravité cliniques et paracliniques","q":"Quels sont les trois principaux critères de gravité clinique majeurs qui justifient une hospitalisation en soins intensifs pour une infection bronchopulmonaire communautaire (PAC) chez l'adulte ?","a":"<p>Devant une PAC, les critères majeurs justifiant une admission directe en USI/réanimation sont :</p><ul><li>Un <strong>choc septique</strong> nécessitant des vasopresseurs.</li><li>Une <strong>insuffisance respiratoire aiguë</strong> nécessitant une intubation.</li></ul>"},{"i":"fa6fdbe7f554","n":154,"o":"154-6","u":"Identifier une urgence","t":"Savoir rechercher et reconnaître les signes de gravité cliniques et paracliniques","q":"Quand est-il recommandé d'hospitaliser un patient adulte atteint d'une infection bronchopulmonaire communautaire (PAC) ?","a":"<p>Une hospitalisation est recommandée pour toute PAC présentant au moins un des critères suivants :</p><ul><li><strong>≥ 1 signe de gravité</strong> (atteinte des fonctions vitales, signes associés, complications locorégionales, atteintes extra-pulmonaires/systémiques).</li><li><strong>≥ 2 facteurs de risque</strong>.</li><li><strong>≥ 1 facteur de risque ET âge > 65 ans</strong>.</li></ul>"},{"i":"4bc0e13857bb","n":154,"o":"154-7","u":"Examens complémentaires","t":"Connaître les indications à la réalisation d'une radio de thorax chez l'adulte et chez l'enfant","q":"Quand est-il recommandé de réaliser une radiographie thoracique de contrôle après une pneumonie aiguë communautaire (PAC) chez l'adulte et pourquoi ?","a":"<p>Une radiographie thoracique de contrôle est recommandée à <strong>4-6 semaines</strong> post-PAC chez le <strong>patient tabagique</strong> ou <strong>âgé de plus de 50 ans</strong> afin de ne pas méconnaître un <strong>cancer bronchique sous-jacent</strong>.</p>"},{"i":"84c0d2db4af1","n":154,"o":"154-7","u":"Examens complémentaires","t":"Connaître les indications à la réalisation d'une radio de thorax chez l'adulte et chez l'enfant","q":"Quelle est la sémiologie radiologique attendue d'une pneumonie alvéolaire sur une radiographie thoracique ?","a":"<p>Une pneumonie alvéolaire se caractérise par une <strong>condensation systématisée</strong> (segmentaire ou lobaire), <strong>homogène</strong>, <strong>bien limitée</strong>, avec un <strong>bronchogramme aérien</strong>.</p>"},{"i":"97513b1fd4b9","n":154,"o":"154-7","u":"Examens complémentaires","t":"Connaître les indications à la réalisation d'une radio de thorax chez l'adulte et chez l'enfant","q":"Est-ce qu'une radiographie thoracique normale en début d'évolution d'une pneumonie aiguë communautaire (PAC) exclut le diagnostic ?","a":"<p>Non, il peut exister un <strong>retard radiologique</strong> par rapport à la clinique. La radiographie thoracique peut être <strong>normale à H0</strong> de la présentation clinique. De plus, un foyer peut être masqué par les structures anatomiques (cœur, coupole).</p>"},{"i":"c17d586f12f5","n":154,"o":"154-7","u":"Examens complémentaires","t":"Connaître les indications à la réalisation d'une radio de thorax chez l'adulte et chez l'enfant","q":"Quelle est la place de la radiographie thoracique chez l'enfant en cas de bronchite aiguë ou de bronchiolite typique ?","a":"<p>La radiographie thoracique n'est <strong>pas systématique</strong> en cas de bronchite aiguë ou de bronchiolite typique. Elle est indiquée en cas de <strong>signes de gravité</strong>, de <strong>doute diagnostique</strong>, ou de suspicion de <strong>surinfection/complication</strong>.</p>"},{"i":"d17a760458b4","n":154,"o":"154-7","u":"Examens complémentaires","t":"Connaître les indications à la réalisation d'une radio de thorax chez l'adulte et chez l'enfant","q":"Quels sont les objectifs de la radiographie thoracique de face réalisée chez l'adulte en cas de suspicion de pneumonie aiguë communautaire (PAC) ?","a":"<p>Les objectifs sont :</p><ul><li>La <strong>confirmation diagnostique</strong>.</li><li>Le repérage d'un <strong>syndrome de condensation</strong>.</li><li>La recherche d'une <strong>complication locale</strong> (épanchement, excavation).</li><li>La réalisation d'un <strong>bilan de base</strong> avant l'instauration d'une antibiothérapie.</li></ul>"},{"i":"f9dd866bd142","n":154,"o":"154-7","u":"Examens complémentaires","t":"Connaître les indications à la réalisation d'une radio de thorax chez l'adulte et chez l'enfant","q":"Dans quel cas la radiographie thoracique n'est-elle pas systématique chez l'adulte et quelles sont les indications justifiant sa réalisation ?","a":"<p>La radiographie thoracique n'est <strong>pas systématique en cas de bronchite aiguë</strong>. Elle est indiquée en cas de <strong>doute clinique sur une pneumonie</strong> ou de <strong>signes inquiétants</strong>.</p>"},{"i":"fe60b8465821","n":154,"o":"154-7","u":"Examens complémentaires","t":"Connaître les indications à la réalisation d'une radio de thorax chez l'adulte et chez l'enfant","q":"Quelle est l'indication de la radiographie thoracique de face (RXT) chez l'adulte en cas de suspicion de pneumonie aiguë communautaire (PAC) ?","a":"<p>La radiographie thoracique de face est <strong>systématique</strong> chez l'adulte en cas de suspicion de PAC.</p>"}]};